// 產生檔：node tools/build_course_v2.js（來源 tools/content/course_v2/）。不要手改。
window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"critical-points":{"id":"critical-points","prerequisites":["derivative-power-rules","chain-rule","quotient-rule"],"next":["increasing-decreasing"],"related":["domain-range","first-derivative-test","extreme-value-theorem"],"objectives":["分清楚局部極值與絕對極值。","找出一個函數所有的臨界點：f′ = 0 的點，以及 f′ 不存在的點，而且都要在定義域裡面。","在閉區間上用「臨界點＋端點」比大小，求絕對最大值與最小值。"],"concept":[{"heading":"① 山頂與谷底","body":["f 在 c 有局部極大值（也叫相對極大值），意思是：在 c 附近的一小段裡，f(c) 最大。局部極小值同理。兩者合稱局部極值。","絕對最大值是整個考慮範圍裡最大的那個值。局部極大只跟「附近」比，所以一個函數可以有好幾個局部極大，而且不一定是絕對最大。"]},{"heading":"② 光滑的山頂，切線是水平的","body":["在山頂，往左看是上坡、往右看是下坡；如果那裡有切線，它只能是水平的，也就是 f′(c) = 0。這叫 Fermat 定理：f 在定義域內部的點 c 有局部極值，而且 f′(c) 存在，那 f′(c) = 0。","但山頂也可能是尖的。f(x) = |x| 在 0 有極小值，那裡沒有切線，f′(0) 不存在。"]},{"heading":"Fermat 定理的證明","body":["設 f 在 c 有局部極大，而且 f′(c) 存在。在 c 附近，f(c + h) − f(c) ≤ 0。","h > 0 時，(f(c + h) − f(c))/h ≤ 0，所以右極限 f′(c) ≤ 0；h < 0 時，分母是負的，(f(c + h) − f(c))/h ≥ 0，所以左極限 f′(c) ≥ 0。","f′(c) 存在，左右極限相等，只能是 0。局部極小的情形把不等號反過來，論證一樣。"],"collapsible":true},{"heading":"③ 臨界點的定義","body":["c 是 f 的臨界點，意思是：c 在 f 的定義域內部，而且 f′(c) = 0 或 f′(c) 不存在。","由 ②，內部的局部極值只會發生在臨界點。所以找極值的第一步，是把臨界點全部列出來。","臨界點只是候選人。f(x) = x³ 的 f′(0) = 0，但 x³ 在 0 只是平一下又繼續往上，不是極值。要判斷是不是極值，看〈一階導數判別〉。"]},{"heading":"④ 閉區間上的最大最小","body":["f 在閉區間 [a, b] 上連續，就一定有絕對最大值與最小值（〈極值定理〉）。它們不是出現在內部，就是出現在端點；在內部的話一定是臨界點。","所以做法是：列出 (a, b) 內的臨界點，連同 a、b 一起代進 f，最大的就是最大值，最小的就是最小值。不用判斷誰是山頂。"]}],"workedExamples":[{"title":"閉區間：臨界點＋端點","prompt":"求 f(x) = x³ − 3x² − 9x + 5 在 [−2, 4] 上的絕對最大值與最小值。","problemId":"lec-04-q1a","steps":["f′(x) = 3x² − 6x − 9 = 3(x² − 2x − 3) = 3(x − 3)(x + 1)。多項式的導數處處存在，臨界點只有 f′ = 0 的 x = −1、x = 3，兩個都在 (−2, 4) 裡。","四個候選點代進 f：f(−2) = −8 − 12 + 18 + 5 = 3；f(−1) = −1 − 3 + 9 + 5 = 10；f(3) = 27 − 27 − 27 + 5 = −22；f(4) = 64 − 48 − 36 + 5 = −15。","最大的是 10（在 x = −1），最小的是 −22（在 x = 3）。"],"answer":"最大值 10，最小值 −22"},{"title":"f′ 不存在的臨界點","prompt":"求 g(x) = x^{2/3}(5 − x) 在 [−1, 5] 上的絕對最大值。","problemId":"lec-04-q1b","steps":["乘法法則：g′(x) = (2/3)x^{−1/3}(5 − x) − x^{2/3}。提出 (1/3)x^{−1/3}：g′(x) = (1/3)x^{−1/3}(2(5 − x) − 3x) = (10 − 5x)/(3x^{1/3})。","g′ = 0：10 − 5x = 0，x = 2。g′ 不存在：分母 x^{1/3} = 0，x = 0。g 在 x = 0 有定義（g(0) = 0），而 0 在區間內部，所以 0 也是臨界點。","代值：g(−1) = (−1)^{2/3} · 6 = 1 · 6 = 6（(−1)^{2/3} = ((−1)^{1/3})² = (−1)² = 1）；g(0) = 0；g(2) = 2^{2/3} · 3 ≈ 4.76；g(5) = 0。","最大值是 6，出現在端點 x = −1。"],"answer":"6","note":"只解 g′ = 0 會漏掉 x = 0。這題的最小值 0 就出現在 x = 0 與 x = 5。"},{"title":"先看定義域","prompt":"求 f(x) = ln x − x 的所有臨界點。","problemId":"si-set-015","steps":["定義域是 x > 0。","f′(x) = 1/x − 1 = (1 − x)/x。f′ = 0 得 x = 1。","f′ 在 x = 0 不存在，但 0 不在定義域裡，所以不是臨界點。","臨界點只有 x = 1。"],"answer":"x = 1"}],"pitfalls":["只解 f′ = 0，漏掉 f′ 不存在的點（尖角、垂直切線）。","把定義域外的點也算成臨界點，例如 ln x − x 的 x = 0。","以為臨界點一定是極值：x³ 在 0 就不是。","閉區間題忘了把端點代進去比。"],"checks":[{"ask":"f(x) = |x − 2| 的臨界點是？","options":[{"label":"x = 2，因為 f′(2) 不存在","correct":true},{"label":"沒有，因為 f′ 從來不等於 0","why":"你只找了 f′ = 0。f′ 不存在的點也算臨界點，|x − 2| 在 2 是尖角。"},{"label":"x = 0","why":"x = 0 是 |x| 的尖角；這裡平移了，尖角在 x = 2。"}]},{"ask":"f(x) = x³ 在 x = 0：","options":[{"label":"是臨界點，但不是極值","correct":true},{"label":"是臨界點，所以是極值","why":"臨界點只是候選人。x³ 在 0 左邊比 0 小、右邊比 0 大，不是極大也不是極小。"},{"label":"不是臨界點","why":"f′(x) = 3x²，f′(0) = 0，而且 0 在定義域內部，符合臨界點的定義。"}]},{"ask":"f(x) = x³ − 3x 在 [0, 2] 上的最大值是？","options":[{"label":"2","correct":true},{"label":"−2","why":"−2 是臨界點 x = 1 的值，那是最小值；還要把端點代進去：f(0) = 0、f(2) = 2。"},{"label":"0","why":"你可能只比了 f(0) 與 f(1)。右端點 f(2) = 8 − 6 = 2 比較大。"}]},{"ask":"局部極大值與絕對最大值的關係？","options":[{"label":"局部極大只跟附近比，不一定是絕對最大","correct":true},{"label":"局部極大一定就是絕對最大","why":"一個函數可以有好幾個局部極大，高度各不相同；而且絕對最大也可能出現在端點。"},{"label":"絕對最大一定是局部極大","why":"絕對最大可能出現在閉區間的端點，例如 x³ − 3x 在 [0, 2] 的最大值在 x = 2；端點不在定義域內部，不算局部極大。"}]}],"practice":[{"id":"lec-04-m1","core":true},{"id":"si-set-002","core":true},{"id":"si-set-015","core":true},{"id":"db-ext-001","core":true},{"id":"lec-04-q1a","core":true},{"id":"si-set-014","core":true},{"id":"lec-04-q1b","core":true},{"id":"si-set-013"},{"id":"si-set-016"},{"id":"db-ext-002"},{"id":"db-ext-003"},{"id":"db-ext-004","challenge":true,"note":"挑戰：sin x + cos x 的臨界點要解 tan x = 1，記得只取 [0, π] 裡的那一個。"}]},"increasing-decreasing":{"id":"increasing-decreasing","prerequisites":["critical-points","intermediate-value-theorem"],"next":["first-derivative-test"],"related":["mean-value-theorem"],"objectives":["用 f′ 的正負判斷 f 在哪些區間遞增、哪些區間遞減。","會畫 f′ 的符號表：找出切點、每段取一個測試點或看因式的正負。","定義域斷開的地方要分段寫，不能把兩段併成一段。"],"concept":[{"heading":"① 遞增、遞減是什麼","body":["f 在區間 I 上遞增：I 裡任取 x₁ < x₂，都有 f(x₁) < f(x₂)。往右走，高度一直變高。遞減就是一直變低。","這是在講一整段區間，不是講一個點。例如 x² 在 (−∞, 0) 上遞減、在 (0, ∞) 上遞增；答案永遠寫成區間，而不是一個個的點。"]},{"heading":"② 斜率是正的，就是上坡","body":["f′(x) 是切線斜率。如果在一整段區間上 f′ > 0，每一點都往上斜，f 在那段遞增；f′ < 0 則遞減。","反過來不完全成立：x³ 在整條數線上遞增，但 f′(0) = 0。遞增的函數，導數可以在個別點等於 0。"]},{"heading":"為什麼 f′ > 0 推得出遞增（用均值定理）","body":["設 f 在區間 I 上可微，而且 I 上處處 f′ > 0。任取 I 裡的 x₁ < x₂。f 在 [x₁, x₂] 上可微，所以也連續，符合〈均值定理〉的條件：存在 c ∈ (x₁, x₂) 使 f(x₂) − f(x₁) = f′(c)(x₂ − x₁)。","右邊 f′(c) > 0、x₂ − x₁ > 0，所以 f(x₂) − f(x₁) > 0。x₁、x₂ 是任取的，所以 f 在 I 上遞增。f′ < 0 的情形同理。"],"collapsible":true},{"heading":"③ 符號表：先找切點，再一段一段看","body":["f′ 只會在兩種地方換號：f′ = 0 或 f′ 不存在的點（包括不在定義域的點）。在兩個切點之間，只要 f′ 連續而且沒有零點，由〈中間值定理〉它就不會換號。本課的函數 f′ 在定義域上都連續。","所以步驟是：寫出定義域 → 求 f′ 並因式分解 → 找出所有切點、把數線切開 → 每一段看 f′ 的正負（代一個測試點，或數負的因式有幾個）→ 正的那段遞增、負的那段遞減。"]},{"heading":"④ 斷開的地方要分開寫","body":["f(x) = x²/(x − 1) 在 (0, 1) 與 (1, 2) 上都遞減，但不能說它在 (0, 1) ∪ (1, 2) 上遞減：f(0.5) = −0.5，f(1.5) = 4.5，右邊的值反而比較大。中間 x = 1 斷開了，兩段要分開寫。"]}],"workedExamples":[{"title":"多項式","prompt":"求 f(x) = x³ − 3x 的遞增、遞減區間。","problemId":"si-int-005","steps":["定義域是全體實數。f′(x) = 3x² − 3 = 3(x − 1)(x + 1)。","切點：x = −1、x = 1，把數線切成三段。","x < −1：x − 1 < 0、x + 1 < 0，兩個負因式相乘為正，f′ > 0。−1 < x < 1：只有 x − 1 為負，f′ < 0。x > 1：兩個都正，f′ > 0。","遞增：(−∞, −1) 與 (1, ∞)；遞減：(−1, 1)。"],"answer":"遞增 (−∞, −1)、(1, ∞)；遞減 (−1, 1)"},{"title":"有一個永遠為正的因式","prompt":"求 f(x) = x e^{−x} 的遞增、遞減區間。","problemId":"lec-04-m5","steps":["乘法法則與連鎖律：f′(x) = e^{−x} + x · (−e^{−x}) = (1 − x)e^{−x}。","e^{−x} 對所有 x 都大於 0，不影響正負；f′ 的正負跟 1 − x 一樣。","x < 1 時 1 − x > 0，f′ > 0；x > 1 時 f′ < 0。","遞增：(−∞, 1)；遞減：(1, ∞)。"],"answer":"遞增 (−∞, 1)；遞減 (1, ∞)"},{"title":"定義域斷開","prompt":"求 f(x) = x²/(x − 1) 的遞增、遞減區間。","problemId":"lec-04-q3c","steps":["定義域：x ≠ 1。","除法法則：f′(x) = (2x(x − 1) − x² · 1)/(x − 1)² = (x² − 2x)/(x − 1)² = x(x − 2)/(x − 1)²。","切點：f′ = 0 的 x = 0、x = 2，以及不在定義域的 x = 1。數線切成四段。","分母 (x − 1)² 在 x ≠ 1 時恆正，正負看 x(x − 2)：x < 0 為正；0 < x < 1 與 1 < x < 2 為負；x > 2 為正。","遞增：(−∞, 0)、(2, ∞)；遞減：(0, 1)、(1, 2)，這兩段要分開寫。"],"answer":"遞增 (−∞, 0)、(2, ∞)；遞減 (0, 1)、(1, 2)"}],"pitfalls":["只找 f′ = 0 的點，漏了定義域斷開的點。","把斷開的兩段寫成一段遞減（x²/(x − 1) 的 (0, 1) 與 (1, 2)）。","把恆正的因式（e^{−x}、平方）也拿來切數線，或因此搞錯正負。","以為遞增就要處處 f′ > 0：x³ 在 0 的導數是 0，照樣遞增。"],"checks":[{"ask":"f′(x) = (x − 2)e^{x}。f 在哪裡遞增？","options":[{"label":"(2, ∞)","correct":true},{"label":"(−∞, 2)","why":"x < 2 時 x − 2 < 0，而 eˣ > 0，f′ 是負的，那是遞減。"},{"label":"全體實數","why":"eˣ 恆正，但 x − 2 會變號；正負要看 x − 2。"}]},{"ask":"f′(x) = x(x − 3)。在 (0, 3) 上 f′ 的正負與 f 的走向？","options":[{"label":"f′ < 0，f 遞減","correct":true},{"label":"f′ > 0，f 遞增","why":"代測試點 x = 1：1 · (−2) = −2 < 0。0 與 3 之間只有 x − 3 是負的。"},{"label":"無法判斷","why":"f′ 是多項式、連續，在 0 與 3 之間沒有零點，所以整段同號，代一點就知道。"}]},{"ask":"f(x) = 1/x 在 (−∞, 0) 與 (0, ∞) 都遞減。可以說 f 在 (−∞, 0) ∪ (0, ∞) 上遞減嗎？","options":[{"label":"不行，f(−1) = −1 < f(1) = 1","correct":true},{"label":"可以，兩段都遞減，合起來也遞減","why":"遞減要求任取 x₁ < x₂ 都有 f(x₁) > f(x₂)。x₁ = −1、x₂ = 1 就不成立。"},{"label":"可以，因為 f′ = −1/x² 處處是負的","why":"f′ 只在定義域上是負的；x = 0 斷開，均值定理不能跨過去用。"}]},{"ask":"f′ > 0 推出 f 遞增，這件事的證明用到哪個定理？","options":[{"label":"均值定理","correct":true},{"label":"中間值定理","why":"中間值定理用在判斷 f′ 在兩個切點之間不換號；把「斜率為正」變成「右邊比較高」靠的是均值定理。"},{"label":"Fermat 定理","why":"Fermat 定理講的是極值點的導數為 0，跟遞增無關。"}]}],"practice":[{"id":"si-int-005","core":true},{"id":"si-int-016","core":true},{"id":"lec-04-m5","core":true},{"id":"si-int-017","core":true},{"id":"si-int-018","core":true},{"id":"lec-04-q3c","core":true},{"id":"si-int-019"},{"id":"si-int-020"},{"id":"si-int-021","challenge":true,"note":"挑戰：f′ = 1 − 2cos x，要在 (0, 2π) 裡解 cos x = 1/2，再看兩段之間的正負。"},{"id":"px-mvt-002","challenge":true,"note":"挑戰：寫出 f′ > 0 ⇒ 遞增的證明，就是本課可折疊的那一段。"}]},"first-derivative-test":{"id":"first-derivative-test","prerequisites":["critical-points","increasing-decreasing"],"next":["second-derivative"],"related":["mean-value-theorem","second-derivative-test"],"objectives":["在每個臨界點看 f′ 左右的正負，判斷是局部極大、局部極小，還是都不是。","看出偶次方因式不會讓 f′ 換號，所以那裡不是極值。","只給 f′ 的式子或圖形，也能判斷 f 的極值位置。"],"concept":[{"heading":"① 先下坡再上坡，中間就是谷底","body":["〈增減區間〉告訴我們 f′ 的正負就是上坡下坡。設 c 是臨界點、f 在 c 連續：","f′ 在 c 的左邊正、右邊負：先上坡再下坡，f(c) 是局部極大。","f′ 在 c 的左邊負、右邊正：先下坡再上坡，f(c) 是局部極小。","f′ 在 c 的兩邊同號：一路上坡（或一路下坡），c 不是極值。"]},{"heading":"② f′(c) 不存在也能用","body":["判別只看 c 左右兩側的 f′，不需要 f′(c) 本身。f(x) = |x| 在 0 沒有導數，但左邊 f′ = −1、右邊 f′ = 1，所以 0 是局部極小。條件是 f 在 c 要連續；在 c 跳開的函數，左右的坡度說明不了 f(c) 本身的高度。"]},{"heading":"③ 偶次方的因式不換號","body":["f′ 因式分解之後，看每個因式在切點兩側有沒有換號。(x − 3) 這種一次因式過了 x = 3 會換號；(x − 1)²、x⁴ 這種偶次方因式恆不為負，過了零點不換號。","所以 f′(x) = (x + 2)(x − 1)² 在 x = 1 兩邊同號，x = 1 是臨界點但不是極值；在 x = −2 換號，那裡才是極值。"]},{"heading":"④ 完整步驟","body":["求 f′ 並因式分解 → 列出臨界點 → 畫 f′ 的符號表（跟〈增減區間〉一樣）→ 每個臨界點讀左右的正負：正變負是極大、負變正是極小、不變不是極值 → 把是極值的點代回 f，求出極值本身。","最後一步常被忘記：題目問「局部極大值」，要的是 f(c) 這個高度；問「在哪裡」，要的才是 c。"]},{"heading":"為什麼左正右負就是局部極大","body":["設 f 在 c 連續，在 (c − δ, c) 與 (c, c + δ) 上可微，而且前一段 f′ > 0、後一段 f′ < 0。","任取 x ∈ (c − δ, c)。f 在 [x, c] 上連續（右端點用的是「f 在 c 連續」）、在 (x, c) 上可微，由〈均值定理〉有 ξ ∈ (x, c) 使 f(c) − f(x) = f′(ξ)(c − x)。f′(ξ) > 0、c − x > 0，所以 f(x) < f(c)。","任取 x ∈ (c, c + δ)，同樣有 ξ ∈ (c, x) 使 f(x) − f(c) = f′(ξ)(x − c) < 0，所以 f(x) < f(c)。","c 附近每一點都比 f(c) 低，f(c) 是局部極大。另外兩種情形把不等號換掉，論證一樣。"],"collapsible":true}],"workedExamples":[{"title":"有一個臨界點不是極值","prompt":"f(x) = x⁴ − 4x³。找出所有局部極值。","problemId":"db-ext-012","steps":["f′(x) = 4x³ − 12x² = 4x²(x − 3)。臨界點：x = 0、x = 3。","4x² 恆 ≥ 0，只在 0 等於 0，不換號；正負看 x − 3。","x < 0：f′ < 0。0 < x < 3：f′ < 0。x > 3：f′ > 0。","x = 0 兩邊都是負，不是極值。x = 3 由負變正，是局部極小，f(3) = 81 − 108 = −27。"],"answer":"只有局部極小 f(3) = −27；x = 0 不是極值"},{"title":"只給 f′","prompt":"某函數的導函數是 f′(x) = (x + 2)(x − 1)²。f 的局部極值在哪裡？","problemId":"lec-04-q4a","steps":["臨界點：x = −2、x = 1（多項式 f′ 處處存在）。","(x − 1)² 恆 ≥ 0，正負看 x + 2。","x < −2：f′ < 0。−2 < x < 1：f′ > 0。x > 1：f′ > 0。","x = −2 由負變正，是局部極小。x = 1 兩邊都正，不是極值。"],"answer":"x = −2 是局部極小；x = 1 不是極值"},{"title":"三角函數","prompt":"f(x) = x − 2 sin x，0 < x < 2π。找出局部極值。","steps":["f′(x) = 1 − 2cos x。f′ = 0：cos x = 1/2，在 (0, 2π) 裡是 x = π/3、x = 5π/3。","0 < x < π/3：cos x > 1/2，f′ < 0。π/3 < x < 5π/3：cos x < 1/2，f′ > 0。5π/3 < x < 2π：cos x > 1/2，f′ < 0。","x = π/3 由負變正，局部極小 f(π/3) = π/3 − 2 · (√3/2) = π/3 − √3 ≈ −0.685。","x = 5π/3 由正變負，局部極大 f(5π/3) = 5π/3 − 2 · (−√3/2) = 5π/3 + √3 ≈ 6.968。"],"answer":"局部極小 π/3 − √3（x = π/3）；局部極大 5π/3 + √3（x = 5π/3）"}],"pitfalls":["看到臨界點就宣布是極值，沒有檢查 f′ 有沒有換號。","把偶次方因式 (x − 1)² 也當成會換號。","左右弄反：先正後負是極大（上坡再下坡），不是極小。","題目給的是 f′ 的圖，卻去找 f′ 的山頂；f 的極值看的是 f′ 穿過 x 軸的地方。"],"checks":[{"ask":"f′ 在 x = 2 左邊為負、右邊為正，f 在 2 連續。x = 2 是？","options":[{"label":"局部極小","correct":true},{"label":"局部極大","why":"左負右正是先下坡再上坡，那是谷底。先上再下才是山頂。"},{"label":"不是極值","why":"f′ 有換號就是極值；兩邊同號才不是。"}]},{"ask":"f′(x) = x²(x − 2)。x = 0 是？","options":[{"label":"不是極值","correct":true},{"label":"局部極大","why":"x² 在 0 兩側都是正的，正負只看 x − 2，在 0 兩側都是負，f′ 沒換號。"},{"label":"局部極小","why":"x = 0 附近 f′ 都是負的，f 一路下坡；真正的局部極小在 x = 2。"}]},{"ask":"圖上是 f′ 的圖形（不是 f）。f 的局部極大出現在哪？","options":[{"label":"f′ 的圖由上往下穿過 x 軸的地方","correct":true},{"label":"f′ 的圖的最高點","why":"那是 f′ 最大、f 爬得最快的地方，不是 f 的山頂。f 的山頂要 f′ 由正變負。"},{"label":"f′ 的圖由下往上穿過 x 軸的地方","why":"由下往上是 f′ 由負變正，那是 f 的局部極小。"}]},{"ask":"f(x) = |x| 在 0 沒有導數。0 是不是 f 的局部極值？","options":[{"label":"是局部極小，因為左邊 f′ = −1、右邊 f′ = 1","correct":true},{"label":"不能判斷，因為 f′(0) 不存在","why":"一階導數判別只看 c 的左右兩側，不需要 f′(c)；需要的是 f 在 0 連續，|x| 是連續的。"},{"label":"不是，因為只有 f′ = 0 的點才可能是極值","why":"f′ 不存在的點也是臨界點，尖角常常就是極值。"}]}],"practice":[{"id":"gx-001","core":true},{"id":"gx-002","core":true},{"id":"lec-04-q4a","core":true},{"id":"lec-04-q4b","core":true},{"id":"gi-004","core":true},{"id":"gx-006","core":true},{"id":"gx-004"},{"id":"gx-003"},{"id":"gx-007"},{"id":"gx-009"},{"id":"gx-010"},{"id":"db-ext-012","challenge":true,"note":"挑戰：x = 0 也是臨界點，但 4x² 不換號。"},{"id":"gx-008","challenge":true,"note":"挑戰：f′ = x²(x − 2) 在 0 碰到 x 軸卻沒有穿過去。"}]},"second-derivative":{"id":"second-derivative","prerequisites":["higher-derivatives","increasing-decreasing"],"next":["concavity"],"related":["first-derivative-test"],"objectives":["說出 f″ 在問什麼：f′（斜率）變化得多快。","用 f″ 的正負判斷 f′ 在哪裡遞增、哪裡遞減。","在直線運動裡由位置求速度、加速度，並判斷速率在變大還是變小。"],"concept":[{"heading":"① f″ 量的是「斜率怎麼變」","body":["f′(x) 是切線斜率。把 f′ 當成一個新的函數，再微分一次，得到 f″(x)：斜率每往右一單位，變化多少。","最熟悉的例子是運動。位置 s(t) 微分是速度 v(t) = s′(t)，再微分是加速度 a(t) = s″(t)。加速度不是「跑多快」，是「速度變化得多快」。"]},{"heading":"② f″ 的正負 → f′ 的增減","body":["把〈增減區間〉用在 f′ 身上：f″ > 0 的區間，f′ 遞增；f″ < 0 的區間，f′ 遞減。","f′ 遞增的意思是切線越來越往上翹：斜率從 −2、−1、0、1、2 一路變大，曲線像碗一樣往上彎。這就是下一課〈凹向上／凹向下〉的內容。","讀圖的版本：f″ 是 f′ 圖形的斜率。f′ 的圖往上走的地方，f″ > 0。"]},{"heading":"③ 加速與減速：看 v 和 a 是否同號","body":["「加速」在日常用語裡指速率 |v| 變大，跟 a 的正負不是同一件事。v = −5 而 a = −2：速度往負方向越來越大，速率在變大。","規則：在一段時間裡 v 與 a 同號，速率增加；異號，速率減少。原因是 (v²)′ = 2va。va > 0 時 v² 遞增，速率 |v| = √(v²) 也跟著遞增；va < 0 時則遞減。"]},{"heading":"④ 記號，以及 f″ 可能不存在","body":["f″(x)、y″、d²y/dx² 都是同一個東西。d²y/dx² 的寫法來自把 d/dx 作用兩次：d/dx(dy/dx)。","f′ 存在，不保證 f″ 存在。f(x) = x|x| 的導函數是 f′(x) = 2|x|，在 0 有尖角，所以 f″(0) 不存在。之後找 f″ 換號的點時，這種點也要列進去。"]}],"workedExamples":[{"title":"算 f″，看 f′ 的增減","prompt":"f(x) = x eˣ。求 f″，並說出 f′ 在哪裡遞增。","problemId":"der-029","steps":["乘法法則：f′(x) = eˣ + x eˣ = (x + 1)eˣ。","再用一次乘法法則：f″(x) = eˣ + (x + 1)eˣ = (x + 2)eˣ。","eˣ 恆正，f″ 的正負跟 x + 2 一樣：x > −2 時 f″ > 0。","所以 f′ 在 (−2, ∞) 上遞增，在 (−∞, −2) 上遞減。"],"answer":"f″(x) = (x + 2)eˣ；f′ 在 (−2, ∞) 遞增"},{"title":"直線運動：何時在加速","prompt":"質點位置 s(t) = t³ − 6t² + 9t（t ≥ 0）。求 a(4)，以及速率增加的時段。","problemId":"lec-02-q4d","steps":["v(t) = 3t² − 12t + 9 = 3(t − 1)(t − 3)；a(t) = 6t − 12 = 6(t − 2)。a(4) = 24 − 12 = 12。","v 在 t = 1、3 換號；a 在 t = 2 換號。把 t ≥ 0 切成四段看符號：","(0, 1)：v > 0、a < 0，異號，減速。(1, 2)：v < 0、a < 0，同號，加速。(2, 3)：v < 0、a > 0，減速。(3, ∞)：v > 0、a > 0，加速。","速率增加的時段是 (1, 2) 與 (3, ∞)。"],"answer":"a(4) = 12；速率在 (1, 2)、(3, ∞) 增加","note":"在 (1, 2) 裡 a < 0，但質點正在加速：它往負方向跑得越來越快。"},{"title":"只給 f′","prompt":"f′(x) = x³ − 4x。f′ 在哪些區間遞增？","steps":["f″(x) = 3x² − 4。f″ = 0：x² = 4/3，x = ±2/√3 ≈ ±1.155。","3x² − 4 是開口向上的拋物線，在兩根之外為正、之間為負。","f′ 遞增：(−∞, −2/√3) 與 (2/√3, ∞)；遞減：(−2/√3, 2/√3)。"],"answer":"(−∞, −2/√3) 與 (2/√3, ∞)"}],"pitfalls":["把 f″ > 0 讀成「f 遞增」。f″ > 0 說的是 f′ 遞增，f 本身可能正在下坡。","以為 a < 0 就是減速；要看 v 和 a 是否同號。","第二次微分時把第一次的結果抄錯，或乘法法則只做一半。","看 f′ 的圖找 f″ 的正負時，去看 f′ 在 x 軸上方還是下方；要看的是 f′ 的圖往上還是往下走。"],"checks":[{"ask":"某一段區間上 f′ < 0、f″ > 0。這段的 f：","options":[{"label":"在下坡，但坡越來越緩","correct":true},{"label":"在上坡","why":"上坡要 f′ > 0。f″ > 0 只說斜率在變大（例如 −3 變 −1），斜率本身仍是負的。"},{"label":"在下坡，而且越來越陡","why":"越來越陡是斜率越來越負，那是 f′ 遞減，要 f″ < 0。"}]},{"ask":"某時刻 v = −4、a = −3。質點的速率：","options":[{"label":"正在增加","correct":true},{"label":"正在減少，因為 a < 0","why":"a 的正負只說速度往哪個方向變。v 和 a 都是負的，速度往負方向越來越大，速率在增加。"},{"label":"不變","why":"a ≠ 0，速度一定在變；va = 12 > 0，所以 v² 在增加，速率也在增加。"}]},{"ask":"s(t) = t³ − 6t² + 9t。a(t) 是？","options":[{"label":"6t − 12","correct":true},{"label":"3t² − 12t + 9","why":"這是 v(t) = s′(t)。加速度要再微分一次。"},{"label":"6t","why":"−12t 微分是 −12，漏掉了。"}]},{"ask":"圖上是 f′ 的圖形。f″ > 0 的地方在哪？","options":[{"label":"f′ 的圖往上走的地方","correct":true},{"label":"f′ 的圖在 x 軸上方的地方","why":"在 x 軸上方是 f′ > 0，那說的是 f 遞增。f″ 是 f′ 的斜率，要看 f′ 的圖往哪裡走。"},{"label":"f′ 的圖穿過 x 軸的地方","why":"f′ 穿過 x 軸是 f 的臨界點，跟 f″ 的正負無關。"}]}],"practice":[{"id":"lec-02-q4a","core":true},{"id":"db-mot-002","core":true},{"id":"der-029","core":true},{"id":"dd-kin-004","core":true},{"id":"exam-der-007","core":true},{"id":"lec-02-q4d","core":true},{"id":"dd-kin-003"},{"id":"uni-der-005"},{"id":"gx-005","challenge":true,"note":"挑戰：圖上是 f′ = x³ − 4x；f′ 的山頂與谷底就是 f″ 換號的地方。"}]},"concavity":{"id":"concavity","prerequisites":["second-derivative","increasing-decreasing"],"next":["inflection-points"],"related":["mean-value-theorem","linear-approximation"],"objectives":["說出凹向上、凹向下的定義：f′ 在區間上遞增或遞減。","用 f″ 的正負求凹向上、凹向下的區間，定義域斷開處分段寫。","知道凹向上時曲線在切線上方，並用它判斷切線估計是高估還是低估。"],"concept":[{"heading":"① 碗口朝上、碗口朝下","body":["y = x² 像一個碗口朝上的碗，y = −x² 碗口朝下。差別在切線的斜率怎麼變：沿著 x² 往右走，斜率從負變到正、一路變大；沿著 −x² 走，斜率一路變小。","所以「彎的方向」可以用斜率的變化來描述，不需要靠眼睛看。這比「看起來像碗」精確，也能算：斜率的變化率就是上一課的 f″。"]},{"heading":"② 定義","body":["設 f 在區間 I 上可微。f′ 在 I 上遞增，就說 f 在 I 上凹向上；f′ 在 I 上遞減，就說 f 在 I 上凹向下。","注意凹性跟 f 本身遞增或遞減無關：x² 在 (−∞, 0) 上是下坡，但整段都凹向上。","名詞提醒：有些書用「凸函數」「凹函數」，而且不同書的用法剛好相反。本課程只說凹向上、凹向下，不會混淆。"]},{"heading":"③ 用 f″ 判斷","body":["f′ 遞增或遞減，由 f′ 的導數 f″ 決定（〈增減區間〉用在 f′ 上）：在區間 I 上 f″ > 0，f 在 I 上凹向上；f″ < 0，凹向下。","步驟跟找增減區間一樣，只是對象換成 f″：求 f″ 並因式分解 → 找 f″ = 0、f″ 不存在、以及不在定義域的點 → 切開數線 → 每段看 f″ 的正負。"]},{"heading":"④ 曲線與切線的位置","body":["凹向上的那一段，曲線在每一條切線的上方；凹向下時在下方。所以在凹向上的地方用切線估計函數值（〈線性近似〉），會低估；凹向下則會高估。"]},{"heading":"為什麼凹向上的曲線在切線上方","body":["設 f 在 I 上可微、f′ 在 I 上遞增，a ∈ I。要證：I 裡每個 x ≠ a 都有 f(x) > f(a) + f′(a)(x − a)。","x > a：由〈均值定理〉，有 c ∈ (a, x) 使 f(x) − f(a) = f′(c)(x − a)。c > a 而 f′ 遞增，所以 f′(c) > f′(a)；乘上正數 x − a，得 f(x) − f(a) > f′(a)(x − a)。","x < a：同樣有 c ∈ (x, a) 使 f(a) − f(x) = f′(c)(a − x)。c < a，所以 f′(c) < f′(a)；乘上正數 a − x，得 f(a) − f(x) < f′(a)(a − x)，移項就是 f(x) > f(a) + f′(a)(x − a)。"],"collapsible":true}],"workedExamples":[{"title":"三次多項式","prompt":"求 f(x) = x³ − 3x² 凹向上、凹向下的區間。","problemId":"gx-051","steps":["f′(x) = 3x² − 6x，f″(x) = 6x − 6 = 6(x − 1)。","f″ = 0 在 x = 1。x < 1 時 f″ < 0，x > 1 時 f″ > 0。","凹向下：(−∞, 1)；凹向上：(1, ∞)。"],"answer":"凹向下 (−∞, 1)；凹向上 (1, ∞)"},{"title":"先除再微分","prompt":"求 f(x) = x²/(x − 1) 凹向上、凹向下的區間。","problemId":"lec-04-q3d","steps":["長除法：x² = (x − 1)(x + 1) + 1，所以 f(x) = x + 1 + 1/(x − 1)（x ≠ 1）。這樣微分比除法法則省事。","f′(x) = 1 − 1/(x − 1)²，f″(x) = 2/(x − 1)³。","f″ 沒有零點，只在不屬於定義域的 x = 1 換號：x > 1 時 (x − 1)³ > 0，f″ > 0；x < 1 時 f″ < 0。","凹向上：(1, ∞)；凹向下：(−∞, 1)。"],"answer":"凹向上 (1, ∞)；凹向下 (−∞, 1)"},{"title":"有一個恆正因式","prompt":"求 f(x) = x e^{−x} 凹向上的區間。","problemId":"gx-052","steps":["f′(x) = (1 − x)e^{−x}。","再用乘法法則：f″(x) = −e^{−x} + (1 − x)(−e^{−x}) = (x − 2)e^{−x}。","e^{−x} > 0，正負看 x − 2：x > 2 時 f″ > 0。","凹向上：(2, ∞)；凹向下：(−∞, 2)。"],"answer":"(2, ∞)"}],"pitfalls":["用 f′ 的正負判斷凹性。f′ 管上坡下坡，凹性要看 f″。","以為凹向上就是遞增：x² 在 x < 0 時凹向上，但在下坡。","f″ 換號的點只找 f″ = 0，漏掉定義域斷開的點（x²/(x − 1) 的 x = 1）。","混用「凸函數／凹函數」，不同書定義相反；只說凹向上、凹向下。"],"checks":[{"ask":"f″(x) = 12x² − 12。f 在哪裡凹向下？","options":[{"label":"(−1, 1)","correct":true},{"label":"(−∞, −1) 與 (1, ∞)","why":"這兩段 12x² − 12 > 0，那是凹向上。代 x = 0：f″ = −12 < 0，凹向下在中間。"},{"label":"(−∞, 0)","why":"你可能看的是 f′ 或 f″ 的某一個因式。f″ = 12(x − 1)(x + 1)，零點在 ±1。"}]},{"ask":"f 在某區間上凹向上。下面哪一個一定成立？","options":[{"label":"f′ 在這個區間上遞增","correct":true},{"label":"f 在這個區間上遞增","why":"凹性管的是 f′ 的增減，不是 f 的增減。x² 在 (−∞, 0) 上凹向上，卻是遞減。"},{"label":"f′ > 0","why":"f′ 可以是負的、只是越來越大，例如 x² 在 x < 0 時 f′ = 2x < 0。"}]},{"ask":"f 在 a 附近凹向下。用 a 點的切線估計 f(a + 0.1)，結果：","options":[{"label":"高估","correct":true},{"label":"低估","why":"凹向下時曲線在切線下方，切線的值比真正的函數值大，是高估。低估是凹向上的情形。"},{"label":"剛好相等","why":"只有在切點本身相等；離開切點，曲線就跟切線分開了。"}]},{"ask":"f(x) = sin x，0 < x < 2π。f 在哪裡凹向上？","options":[{"label":"(π, 2π)","correct":true},{"label":"(0, π)","why":"f″ = −sin x。在 (0, π) 上 sin x > 0，f″ < 0，是凹向下。"},{"label":"(π/2, 3π/2)","why":"那是 f′ = cos x < 0 的地方，說的是 f 遞減，不是凹性。"}]}],"practice":[{"id":"gx-051","core":true},{"id":"lec-04-q3d","core":true},{"id":"gx-052","core":true},{"id":"gx-053","core":true},{"id":"gx-054","core":true},{"id":"ig-num-009","challenge":true,"note":"挑戰：梯形法用的是割線；凹向上時割線在曲線上方，所以高估。跟切線（低估）方向相反。"}]},"inflection-points":{"id":"inflection-points","prerequisites":["concavity"],"next":["second-derivative-test"],"related":["first-derivative-test","increasing-decreasing"],"objectives":["說出反曲點的定義：f 在該點連續，而且凹性在那裡改變。","列出候選點（f″ = 0 或 f″ 不存在），再逐一檢查 f″ 有沒有換號。","知道 f″(c) = 0 既不保證是反曲點，反曲點也不一定有 f″(c) = 0。"],"concept":[{"heading":"① 彎的方向換邊的地方","body":["x³ − 3x² 在 x = 1 左邊凹向下、右邊凹向上。曲線在這一點從「碗口朝下」換成「碗口朝上」，這種點叫反曲點。","定義：f 在 c 連續，而且在 c 的一側凹向上、另一側凹向下，就說點 (c, f(c)) 是 f 的反曲點。反曲點是圖形上的一個點，答案可以寫座標，題目只問位置時寫 x = c。"]},{"heading":"② 候選點：f″ = 0 或 f″ 不存在","body":["凹性由 f″ 的正負決定，所以凹性只可能在 f″ 換號的地方改變，跟〈增減區間〉找切點的道理一樣。候選點是定義域裡 f″ = 0 或 f″ 不存在的點。","然後每個候選點都要檢查：f″ 在兩側有沒有換號。換號才是反曲點。"]},{"heading":"③ f″(c) = 0 不夠，也不必要","body":["不夠：f(x) = x⁴，f″(x) = 12x²，f″(0) = 0。但 12x² 在 0 兩側都是正的，整條曲線都凹向上，0 不是反曲點。","不必要：f(x) = ∛x，f″(x) = −(2/9)x^{−5/3}，在 0 不存在。x < 0 時 f″ > 0、x > 0 時 f″ < 0，凹性換了，而 ∛x 在 0 連續，所以原點是反曲點。","還有一種：凹性換了，但那一點不在定義域裡。x²/(x − 1) 在 x = 1 兩側凹性不同，可是 f(1) 沒有定義，所以沒有反曲點。"]},{"heading":"f″ 連續時，反曲點一定有 f″(c) = 0","body":["設 f″ 在 c 附近存在且在 c 連續，而 (c, f(c)) 是反曲點。假如 f″(c) > 0，由連續性，c 附近一小段 (c − δ, c + δ) 上都有 f″ > 0，那 f 在 c 的兩側都凹向上，凹性沒有改變，矛盾。f″(c) < 0 同理。所以 f″(c) = 0。","這個結論需要「f″ 在 c 存在且連續」；∛x 不符合這個條件，所以不衝突。"],"collapsible":true}],"workedExamples":[{"title":"偶次多項式","prompt":"求 f(x) = x⁴ − 6x² 的反曲點。","problemId":"si-set-017","steps":["f′(x) = 4x³ − 12x，f″(x) = 12x² − 12 = 12(x − 1)(x + 1)。","候選點：x = −1、x = 1（f″ 處處存在）。","x < −1：f″ > 0。−1 < x < 1：f″ < 0。x > 1：f″ > 0。兩個候選點都換號。","f(±1) = 1 − 6 = −5。反曲點是 (−1, −5) 與 (1, −5)。"],"answer":"(−1, −5)、(1, −5)"},{"title":"只給 f′","prompt":"某函數的導函數是 f′(x) = (x + 2)(x − 1)²。求 f 所有反曲點的 x 座標。","problemId":"lec-04-q4c","steps":["對 f′ 用乘法法則：f″(x) = (x − 1)² + (x + 2) · 2(x − 1)。","提出 (x − 1)：f″(x) = (x − 1)((x − 1) + 2(x + 2)) = (x − 1)(3x + 3) = 3(x − 1)(x + 1)。","f″ 在 x = −1、x = 1 都是一次因式的零點，兩側換號。","反曲點在 x = −1 與 x = 1。"],"answer":"x = −1、x = 1","note":"x = 1 同時是臨界點（f′(1) = 0）和反曲點：切線水平，曲線穿過切線，所以不是極值。"},{"title":"f″ 不存在的反曲點","prompt":"f(x) = ∛x = x^{1/3}。原點是不是反曲點？","steps":["x ≠ 0 時：f′(x) = (1/3)x^{−2/3}，f″(x) = −(2/9)x^{−5/3}。在 x = 0 這兩個式子都沒有意義，f″(0) 不存在。","x > 0：x^{−5/3} > 0，f″ < 0，凹向下。x < 0：x^{−5/3} = 1/(∛x)⁵ < 0，f″ > 0，凹向上。","∛x 在 0 連續，凹性在 0 改變，所以原點 (0, 0) 是反曲點。"],"answer":"是，原點是反曲點"}],"pitfalls":["解出 f″ = 0 就宣布是反曲點，沒有檢查換號（x⁴ 的 0）。","只找 f″ = 0，漏掉 f″ 不存在的點（∛x 的 0）。","把不在定義域的點也算成反曲點（x²/(x − 1) 的 1）。","把 f′ = 0 的點當成反曲點候選；那是極值的候選。"],"checks":[{"ask":"f(x) = x⁴。x = 0 是不是反曲點？","options":[{"label":"不是，f″ = 12x² 在 0 兩側都是正的","correct":true},{"label":"是，因為 f″(0) = 0","why":"f″(0) = 0 只是候選。12x² 在 0 兩側都正，整條曲線凹向上，凹性沒換。"},{"label":"是，因為 f′(0) = 0","why":"f′(0) = 0 說的是切線水平，那是極值的候選，跟凹性無關。x⁴ 在 0 是極小值。"}]},{"ask":"f(x) = x³ − 6x² + 5。反曲點的 x 座標是？","options":[{"label":"2","correct":true},{"label":"0 與 4","why":"那是 f′ = 3x² − 12x = 0 的解，是臨界點。反曲點要解 f″ = 6x − 12。"},{"label":"6","why":"f″ = 6x − 12 = 0 解出來是 x = 2，不是 6。"}]},{"ask":"f″(x) = (x − 3)²(x + 1)。f 的反曲點在？","options":[{"label":"只有 x = −1","correct":true},{"label":"x = 3 與 x = −1","why":"(x − 3)² 在 3 兩側都正，f″ 在 3 不換號，凹性沒變。"},{"label":"只有 x = 3","why":"重根不換號；真正換號的是一次因式 x + 1。"}]},{"ask":"f 在 x = 1 沒有定義，f″ 在 1 的兩側一正一負。f 在 x = 1 有反曲點嗎？","options":[{"label":"沒有，反曲點要在圖形上、f 要在那點連續","correct":true},{"label":"有，因為凹性換了","why":"凹性換了還不夠；f(1) 沒有定義，圖形上根本沒有這一點。x²/(x − 1) 就是這種情形。"},{"label":"要看 f″(1) 是不是 0","why":"f 在 1 沒定義，f″(1) 也不存在；問題出在那一點不在定義域。"}]}],"practice":[{"id":"cx-curve-001","core":true},{"id":"si-set-019","core":true},{"id":"gi-002","core":true},{"id":"si-set-017","core":true},{"id":"cx-curve-002","core":true},{"id":"si-set-018","core":true},{"id":"lec-04-q4c","core":true},{"id":"cx-curve-008"},{"id":"gi-006"},{"id":"gi-007"},{"id":"gi-008"},{"id":"cx-curve-007"},{"id":"gx-005"},{"id":"db-ext-011","challenge":true,"note":"挑戰：x²e^{−x} 的 f″ = (x² − 4x + 2)e^{−x}，要解二次方程。"},{"id":"dx-bio-002","challenge":true,"note":"挑戰：成長最快的時刻就是 P′ 最大、P 的反曲點。"}]},"second-derivative-test":{"id":"second-derivative-test","prerequisites":["first-derivative-test","concavity"],"next":["asymptotes"],"related":[],"objectives":["在 f′(c) = 0 的點，用 f″(c) 的正負判斷局部極大或極小。","知道 f″(c) = 0 時這個判別不給結論，要改用〈一階導數判別〉。","會挑方法：f″ 好算就用二階，不好算或判別失效就用一階。"],"concept":[{"heading":"① 平的切線＋碗口方向","body":["在 f′(c) = 0 的點，切線是水平的。如果那附近凹向上（碗口朝上），水平切線就落在碗底，f(c) 是局部極小；凹向下（碗口朝下），水平切線在頂上，f(c) 是局部極大。","這是直覺，不是證明：它用「f″(c) > 0」代表「c 附近凹向上」，但 f″ 只在一點為正，並不直接告訴我們一整段的凹性。嚴格的論證在下面的可折疊區塊，不需要這個假設。"]},{"heading":"② 判別法","body":["設 f′(c) = 0，而且 f″(c) 存在。","f″(c) > 0：f(c) 是局部極小。","f″(c) < 0：f(c) 是局部極大。","f″(c) = 0：判別法不給結論。"],"tex":["f'(c)=0,\\ f''(c)>0\\ \\Rightarrow\\ \\text{局部極小};\\qquad f'(c)=0,\\ f''(c)<0\\ \\Rightarrow\\ \\text{局部極大}"]},{"heading":"③ f″(c) = 0 時，什麼都可能","body":["三個函數在 0 都有 f′(0) = 0、f″(0) = 0：x⁴ 在 0 是局部極小，−x⁴ 是局部極大，x³ 不是極值。同樣的 f″(0) = 0，三種結果都有，所以這時判別法不能下結論，要回去看 f′ 在兩側的正負。","另外，f′(c) 不存在的臨界點（尖角）也不能用二階判別，因為 f″(c) 根本不存在。"]},{"heading":"④ 一階還是二階？","body":["二階判別的好處是只要代一個數：算出 f″(c) 看正負就好，不用畫整張符號表。適合 f″ 好算、臨界點不多的時候。","一階判別比較耐用：f″(c) = 0、f′(c) 不存在、f″ 很難算時都能用。而且它順便給出整段的增減，畫圖時本來就需要。所以習慣是：先試二階，判不出來就回到一階。"]},{"heading":"證明（f″(c) > 0 的情形）","body":["f″(c) 存在，表示 f′ 在 c 附近存在，所以 f 在 c 附近可微、在 c 連續。","由導數定義與 f′(c) = 0：f″(c) = lim_{x→c} (f′(x) − f′(c))/(x − c) = lim_{x→c} f′(x)/(x − c) > 0。","極限是正數，所以存在 δ > 0，使 0 < |x − c| < δ 時 f′(x)/(x − c) > 0。也就是：x ∈ (c − δ, c) 時 x − c < 0，所以 f′(x) < 0；x ∈ (c, c + δ) 時 f′(x) > 0。","f′ 在 c 由負變正，由〈一階導數判別〉，f(c) 是局部極小。f″(c) < 0 的情形同理。"],"collapsible":true}],"workedExamples":[{"title":"兩個臨界點都判得出來","prompt":"f(x) = x³ − 3x。用二階導數判別找局部極值。","problemId":"gi-001","steps":["f′(x) = 3x² − 3 = 3(x − 1)(x + 1)，臨界點 x = −1、x = 1。f″(x) = 6x。","f″(−1) = −6 < 0：局部極大，f(−1) = −1 + 3 = 2。","f″(1) = 6 > 0：局部極小，f(1) = 1 − 3 = −2。"],"answer":"局部極大 f(−1) = 2；局部極小 f(1) = −2"},{"title":"判別失效，改用一階","prompt":"f(x) = x⁴ − 4x³。判斷兩個臨界點。","problemId":"db-ext-012","steps":["f′(x) = 4x²(x − 3)，臨界點 x = 0、x = 3。f″(x) = 12x² − 24x。","f″(3) = 108 − 72 = 36 > 0：局部極小，f(3) = 81 − 108 = −27。","f″(0) = 0：二階判別沒有結論。","改看 f′ 的正負（〈一階導數判別〉）：4x² 不換號，x − 3 在 0 附近是負的，所以 f′ 在 0 兩側都負，x = 0 不是極值。"],"answer":"局部極小 f(3) = −27；x = 0 不是極值"},{"title":"指數函數","prompt":"f(x) = x e^{−x}。找局部極值。","problemId":"gi-004","steps":["f′(x) = (1 − x)e^{−x}，e^{−x} 不為 0，臨界點只有 x = 1。","f″(x) = (x − 2)e^{−x}（〈凹向上／凹向下〉範例 3 算過）。f″(1) = −e^{−1} < 0。","局部極大，f(1) = 1 · e^{−1} = 1/e ≈ 0.368。"],"answer":"局部極大 f(1) = 1/e"}],"pitfalls":["f″(c) = 0 時下結論說「不是極值」。x⁴ 就是反例。","符號記反：f″ > 0 是極小（碗口朝上），不是極大。","對 f′ 不存在的臨界點用二階判別。","判出極大極小之後忘了代回 f 求極值本身。"],"checks":[{"ask":"f′(2) = 0、f″(2) = −5。x = 2 是？","options":[{"label":"局部極大","correct":true},{"label":"局部極小","why":"f″ < 0 是凹向下、碗口朝下，水平切線在頂上，是極大。"},{"label":"無法判斷","why":"只有 f″(c) = 0 才無法判斷；f″(2) = −5 ≠ 0，判別法有結論。"}]},{"ask":"f′(0) = 0、f″(0) = 0。關於 x = 0：","options":[{"label":"二階判別沒有結論，要看 f′ 在兩側的正負","correct":true},{"label":"一定不是極值","why":"x⁴ 在 0 也是 f′ = f″ = 0，卻是局部極小。"},{"label":"一定是反曲點","why":"f″(0) = 0 只是反曲點的候選；x⁴ 在 0 凹性沒換，不是反曲點。"}]},{"ask":"f(x) = x² ln x（x > 0）的臨界點是 x = e^{−1/2}。f″(x) = 2 ln x + 3。這一點是？","options":[{"label":"局部極小","correct":true},{"label":"局部極大","why":"代進去：f″(e^{−1/2}) = 2 · (−1/2) + 3 = 2 > 0，是極小。"},{"label":"無法判斷，因為 ln 是負的","why":"ln(e^{−1/2}) = −1/2 是負的沒關係，要看的是整個 f″ = 2 ln x + 3 = 2 > 0。"}]},{"ask":"f(x) = |x| 在 0 有極小值。能用二階導數判別嗎？","options":[{"label":"不能，f′(0) 與 f″(0) 都不存在","correct":true},{"label":"能，f″(0) = 0 所以無法判斷","why":"|x| 在 0 是尖角，f′(0) 就不存在，更談不上 f″(0)。要用一階導數判別。"},{"label":"能，f″(x) = 0 對 x ≠ 0 成立","why":"判別法要的是 c 這一點本身的 f′(c) = 0 與 f″(c)；兩者在 0 都不存在。"}]}],"practice":[{"id":"gi-001","core":true},{"id":"gi-004","core":true},{"id":"gi-003","core":true},{"id":"db-ext-005","core":true},{"id":"db-ext-012","core":true},{"id":"gx-026"},{"id":"gx-027"},{"id":"gx-029"},{"id":"db-ext-013","challenge":true,"note":"挑戰：二階判別只說 x = 1 是局部極大；要說它是整條數線上的最大值，還要看 x → ±∞ 時 f → 0。"}]},"asymptotes":{"id":"asymptotes","prerequisites":["limit-at-infinity","infinite-limits","polynomial-rational"],"next":["curve-sketching-1"],"related":["limit-factor","limit-rationalize"],"objectives":["用單邊極限判斷垂直漸近線，分清楚「洞」與垂直漸近線。","x → ∞ 與 x → −∞ 分開算，求出水平漸近線（最多兩條）。","用長除法求有理函數的斜漸近線，並說出它的定義：f(x) − (mx + b) → 0。"],"concept":[{"heading":"① 漸近線：曲線越走越貼近的直線","body":["畫圖時，漸近線告訴我們曲線「跑遠了」之後長什麼樣子。三種：垂直的（x 靠近某個數，f 衝到無窮）、水平的（x 跑到無窮，f 靠近一個數）、斜的（x 跑到無窮，f 貼著一條斜線）。"]},{"heading":"② 垂直漸近線與「洞」","body":["x = a 是垂直漸近線：lim_{x→a⁺} f(x) 或 lim_{x→a⁻} f(x) 至少有一個是 +∞ 或 −∞。","有理函數的候選點是分母的零點，但要先約分。分母的零點如果也是分子的零點，約掉之後若不再讓分母為 0，那裡的極限存在，圖形只是挖一個洞，不是漸近線（〈0/0：因式分解〉）。","非有理函數也有：ln x 在 x = 0（x → 0⁺ 時 → −∞），tan x 在 x = π/2。"]},{"heading":"③ 水平漸近線：兩個方向分開看","body":["y = L 是水平漸近線：lim_{x→∞} f(x) = L 或 lim_{x→−∞} f(x) = L。兩個方向可能不同，所以最多有兩條。","x → −∞ 遇到根號要小心：√(x²) = |x|，而 x < 0 時 |x| = −x（〈0/0：有理化〉也提過）。這常是兩邊漸近線不同的原因。","曲線可以穿過水平漸近線：x/(x² + 1) 在 x = 0 就穿過 y = 0。漸近線只描述「跑遠之後」。"]},{"heading":"④ 斜漸近線","body":["y = mx + b（m ≠ 0）是斜漸近線：x → ∞（或 −∞）時 f(x) − (mx + b) → 0，也就是曲線與直線的鉛直距離趨近 0。","有理函數分子次數比分母恰好多 1 時，用長除法寫成 f(x) = mx + b + r(x)/q(x)，餘式 r 的次數小於分母 q，所以 r(x)/q(x) → 0，商式 mx + b 就是斜漸近線。"]}],"workedExamples":[{"title":"垂直漸近線還是洞","prompt":"y = (x − 1)/((x² − 1)(x² − 4)) 有幾條垂直漸近線？","problemId":"cx-curve-006","steps":["分母因式分解：(x − 1)(x + 1)(x − 2)(x + 2)。x ≠ 1 時約掉 x − 1，得 y = 1/((x + 1)(x − 2)(x + 2))。","x = 1：約分後的式子在 1 有定義，極限是 1/(2 · (−1) · 3) = −1/6，圖形在 (1, −1/6) 挖洞，不是漸近線。","x = −1、2、−2：約分後分子是 1、分母趨近 0，單邊極限是 ±∞，都是垂直漸近線。","共 3 條：x = −2、x = −1、x = 2。"],"answer":"3 條"},{"title":"兩條水平漸近線","prompt":"求 f(x) = x/√(x² + 1) 的水平漸近線。","steps":["先把根號裡的 x² 提出來：√(x² + 1) = √(x²) · √(1 + 1/x²) = |x|√(1 + 1/x²)。","x → ∞（x > 0，|x| = x）：f(x) = x/(x√(1 + 1/x²)) = 1/√(1 + 1/x²) → 1。","x → −∞（x < 0，|x| = −x）：f(x) = x/(−x√(1 + 1/x²)) = −1/√(1 + 1/x²) → −1。","水平漸近線是 y = 1（右邊）與 y = −1（左邊）。分母 √(x² + 1) ≥ 1 不為 0，沒有垂直漸近線。"],"answer":"y = 1 與 y = −1"},{"title":"斜漸近線","prompt":"y = (x² + 2x + 3)/x 的斜漸近線是 y = x + k，求 k。","problemId":"cx-curve-005","steps":["分子分母次數 2 比 1，多一次，會有斜漸近線。除法：(x² + 2x + 3)/x = x + 2 + 3/x。","x → ±∞ 時 3/x → 0，所以 y − (x + 2) → 0，斜漸近線是 y = x + 2，k = 2。","順便：x = 0 時分子是 3 ≠ 0、分母是 0，x = 0 是垂直漸近線。"],"answer":"k = 2"}],"pitfalls":["分母為 0 就說是垂直漸近線，沒先約分（會把洞當成漸近線）。","只算 x → ∞，忘了 x → −∞ 可能是另一條。","x → −∞ 時把 √(x²) 寫成 x，正負號全錯。","以為曲線永遠碰不到水平漸近線。","長除法的商寫成斜漸近線，卻忘了先確認分子只比分母多一次。"],"checks":[{"ask":"f(x) = (x² − 4)/(x − 2) 在 x = 2：","options":[{"label":"是一個洞，不是垂直漸近線","correct":true},{"label":"是垂直漸近線，因為分母為 0","why":"分子在 2 也是 0。約分後 f(x) = x + 2（x ≠ 2），極限是 4，有限，所以只是洞。"},{"label":"f 在 2 連續","why":"f(2) 沒有定義（代進去是 0/0），所以不連續；極限存在而已。"}]},{"ask":"y = (2x² + 1)/(x² + 3) 的水平漸近線是？","options":[{"label":"y = 2","correct":true},{"label":"y = 1/3","why":"1/3 是 x = 0 代進去的值。x → ±∞ 要看最高次項的係數比：2/1 = 2。"},{"label":"沒有，因為分子次數不比分母小","why":"次數相等時水平漸近線是最高次係數的比；次數比分母小才是 y = 0。"}]},{"ask":"f(x) = x²/(x − 1) 的斜漸近線是？","options":[{"label":"y = x + 1","correct":true},{"label":"y = x","why":"長除法的商不只 x：x² = (x − 1)(x + 1) + 1，商是 x + 1。"},{"label":"x = 1","why":"x = 1 是垂直漸近線，不是斜漸近線。"}]},{"ask":"lim_{x→−∞} √(x² + 1)/x 是？","options":[{"label":"−1","correct":true},{"label":"1","why":"你把 √(x²) 寫成了 x。x < 0 時 √(x²) = |x| = −x，所以結果是 −1。"},{"label":"不存在","why":"提出 |x| 之後是 −√(1 + 1/x²) → −1，極限存在。"}]}],"practice":[{"id":"lec-04-q3a","core":true},{"id":"lec-01-q4b","core":true},{"id":"cx-curve-004","core":true},{"id":"lec-04-q3b","core":true},{"id":"cx-curve-005","core":true},{"id":"cx-curve-006","core":true},{"id":"lx-app-002"},{"id":"lx-app-008"},{"id":"sk-016"},{"id":"sk-022","challenge":true,"note":"挑戰：畫出 x − 4/x，要同時畫出 x = 0 與 y = x 兩條漸近線。"}]},"curve-sketching-1":{"id":"curve-sketching-1","prerequisites":["asymptotes","increasing-decreasing","first-derivative-test"],"next":["curve-sketching-2"],"related":["domain-range"],"objectives":["照固定順序分析一個函數：定義域、截距、對稱、漸近線、增減與極值。","用奇偶對稱省掉一半的工作。","把分析結果組合成一張草圖的骨架，並解釋為什麼「局部極大可以比局部極小低」。"],"concept":[{"heading":"① 為什麼要有固定順序","body":["描點作圖只能看到你剛好代進去的那幾點，會漏掉洞、漸近線、轉折。函數分析是反過來：先用代數與導數找出圖形的「骨架」，再把曲線填進去。","這一課做前五步，下一課〈函數完整分析 II〉加上凹性與反曲點，完成整張圖。"]},{"heading":"② 五個步驟","body":["1. 定義域：分母不為 0、偶次根號裡 ≥ 0、對數裡 > 0（〈定義域與值域〉）。斷開的地方往往就是漸近線。","2. 截距：y 截距是 f(0)（0 要在定義域裡）；x 截距解 f(x) = 0。","3. 對稱：f(−x) = f(x) 是偶函數，對 y 軸對稱；f(−x) = −f(x) 是奇函數，對原點對稱。有對稱就只要分析 x ≥ 0，另一半照著翻。","4. 漸近線：垂直、水平、斜（〈漸近線〉），並記下曲線從漸近線的哪一側靠近。","5. f′：符號表 → 增減區間 → 局部極值（〈一階導數判別〉），把極值點的座標算出來。"]},{"heading":"③ 把骨架連起來","body":["在座標上畫出漸近線（虛線）、截距、極值點，再依照每一段的上坡下坡把點連起來，靠近漸近線時沿著它延伸。","連的時候常見的意外：局部極大比局部極小低。如果中間隔著一條垂直漸近線，兩個極值在不同的分支上，各自只跟附近比，高低沒有關係。"]}],"workedExamples":[{"title":"有垂直與斜漸近線","prompt":"分析 f(x) = x²/(x − 1)：定義域、截距、對稱、漸近線、增減、極值。","problemId":"lec-04-q3b","steps":["定義域：x ≠ 1。截距：f(0) = 0，f(x) = 0 只有 x = 0，所以只有原點。","對稱：f(−x) = x²/(−x − 1)，既不等於 f(x) 也不等於 −f(x)，沒有對稱。","垂直漸近線 x = 1：x → 1⁺ 時分子 → 1、分母 → 0⁺，f → +∞；x → 1⁻ 時分母 → 0⁻，f → −∞。","斜漸近線：x² = (x − 1)(x + 1) + 1，f(x) = x + 1 + 1/(x − 1)，1/(x − 1) → 0，所以是 y = x + 1。沒有水平漸近線。","f′(x) = x(x − 2)/(x − 1)²（〈增減區間〉範例 3）：遞增 (−∞, 0)、(2, ∞)；遞減 (0, 1)、(1, 2)。","x = 0 由正變負：局部極大 f(0) = 0。x = 2 由負變正：局部極小 f(2) = 4/1 = 4。"],"answer":"定義域 x ≠ 1；截距 (0, 0)；無對稱；漸近線 x = 1、y = x + 1；局部極大 (0, 0)、局部極小 (2, 4)","note":"局部極大 0 比局部極小 4 低：兩點分別在 x = 1 的左右兩個分支上。"},{"title":"用對稱省一半","prompt":"分析 f(x) = x/(x² + 1)：定義域、截距、對稱、漸近線、增減、極值。","problemId":"db-ext-013","steps":["定義域：x² + 1 ≥ 1，全體實數。截距：只有原點 (0, 0)。","對稱：f(−x) = −x/(x² + 1) = −f(x)，奇函數，對原點對稱。下面只看 x ≥ 0。","漸近線：沒有垂直漸近線；分子 1 次、分母 2 次，x → ∞ 時 f → 0，水平漸近線 y = 0（由奇對稱，x → −∞ 也是 y = 0）。","f′(x) = ((x² + 1) − x · 2x)/(x² + 1)² = (1 − x²)/(x² + 1)²。在 x ≥ 0 上：0 ≤ x < 1 時 f′ > 0，x > 1 時 f′ < 0。","x = 1 是局部極大，f(1) = 1/2。翻到左邊：x = −1 是局部極小 f(−1) = −1/2；遞增 (−1, 1)，遞減 (−∞, −1)、(1, ∞)。"],"answer":"奇函數；漸近線 y = 0；遞增 (−1, 1)；局部極大 (1, 1/2)、局部極小 (−1, −1/2)"}],"pitfalls":["跳過定義域，結果在 f 沒定義的地方畫了曲線。","x 截距與 y 截距弄反：y 截距是 f(0)。","只算 x → ∞ 的漸近線，漏了 x → −∞。","看到局部極大比局部極小低，以為算錯；先看兩點中間是不是隔著垂直漸近線。","奇函數只分析了右半邊，忘了把極大翻成極小。"],"checks":[{"ask":"f(x) = x²/(x² − 4) 有哪種對稱？","options":[{"label":"偶函數，對 y 軸對稱","correct":true},{"label":"奇函數，對原點對稱","why":"f(−x) = (−x)²/((−x)² − 4) = x²/(x² − 4) = f(x)，等於自己，是偶函數。"},{"label":"沒有對稱","why":"代 −x 試試：所有 x 都以平方出現，f(−x) = f(x)。"}]},{"ask":"f 的局部極大值是 0、局部極小值是 4。這可能嗎？","options":[{"label":"可能，兩個點之間如果隔著垂直漸近線","correct":true},{"label":"不可能，極大一定比極小高","why":"局部極值只跟附近比。x²/(x − 1) 就是例子：極大 (0, 0) 與極小 (2, 4) 中間隔著 x = 1。"},{"label":"可能，但只有在 f 不連續的點上","why":"這兩個極值點本身 f 都連續、可微；高低反過來是因為它們在不同的分支。"}]},{"ask":"f(x) = (x + 1)/(x − 1) 的漸近線是？","options":[{"label":"x = 1 與 y = 1","correct":true},{"label":"x = 1 與 y = x + 1","why":"分子分母都是 1 次，次數相同，是水平漸近線 y = 1（係數比 1/1），不是斜漸近線。"},{"label":"x = −1 與 y = 1","why":"x = −1 是 x 截距（分子為 0）；垂直漸近線看分母的零點 x = 1。"}]},{"ask":"f(x) = √(x − 2) 的 y 截距是？","options":[{"label":"沒有 y 截距","correct":true},{"label":"(0, √2)","why":"√(0 − 2) = √(−2) 不是實數；0 不在定義域 x ≥ 2 裡，所以沒有 y 截距。"},{"label":"(2, 0)","why":"(2, 0) 是 x 截距（f(2) = 0），不是 y 截距。"}]}],"practice":[{"id":"lec-04-q3a","core":true},{"id":"lec-04-q3b","core":true},{"id":"lec-04-q3c","core":true},{"id":"si-int-019","core":true},{"id":"sk-018","core":true},{"id":"sk-016","core":true},{"id":"sk-019"},{"id":"sk-017"},{"id":"gr-012"},{"id":"gr-010"},{"id":"sk-021","challenge":true,"note":"挑戰：x + 1/x 是奇函數，有垂直漸近線 x = 0 與斜漸近線 y = x；局部極大 −2 比局部極小 2 低。"}]},"curve-sketching-2":{"id":"curve-sketching-2","prerequisites":["curve-sketching-1","concavity","inflection-points"],"next":["optimization-basics"],"related":["second-derivative-test"],"objectives":["在〈函數完整分析 I〉的骨架上加入 f″：凹性區間與反曲點。","把所有結果整理成一張總表，按表自己畫出完整的圖。","用幾個一致性檢查抓出計算錯誤。"],"concept":[{"heading":"① 第六步：f″","body":["求 f″ 並因式分解，找出 f″ = 0、f″ 不存在、以及定義域斷開的點，切開數線。每段看 f″ 的正負：正是凹向上、負是凹向下（〈凹向上／凹向下〉）。凹性換邊、而且 f 在那點有定義的地方是反曲點，把座標算出來（〈反曲點〉）。"]},{"heading":"② 總表","body":["把數線上所有的切點（f′ 的與 f″ 的）合在一起切段，每一段寫出 f′ 與 f″ 的正負。每一段就有四種可能的形狀：","f′ > 0、f″ > 0：上坡，越爬越陡。f′ > 0、f″ < 0：上坡，越爬越緩。f′ < 0、f″ > 0：下坡，越走越緩。f′ < 0、f″ < 0：下坡，越走越陡。","按表畫：先放漸近線、截距、極值點、反曲點，再一段一段照形狀連起來。"]},{"heading":"③ 一致性檢查","body":["畫完之前，幾個檢查可以抓出算錯的地方：","局部極大不會落在凹向上的段裡面，局部極小不會落在凹向下的段裡面；出現這種情形，就是 f′ 或 f″ 有一個算錯了（〈二階導數判別〉）。","偶函數的 f′ 是奇函數、f″ 是偶函數；奇函數則反過來。符號表應該照這個規律對稱。","曲線靠近水平漸近線時，凹性要跟它從哪一側靠近相符：從上方一路往下貼近 y = 0 的尾巴，通常是凹向上。"]}],"workedExamples":[{"title":"接續 I：沒有反曲點的例子","prompt":"f(x) = x²/(x − 1)。加入凹性，完成總表。","problemId":"lec-04-q3d","steps":["f(x) = x + 1 + 1/(x − 1)，f″(x) = 2/(x − 1)³。f″ 沒有零點，只在 x = 1（不在定義域）換號：x < 1 凹向下，x > 1 凹向上。沒有反曲點。","總表切點：0、1、2。(−∞, 0)：f′ +、f″ −，上坡越來越緩。(0, 1)：f′ −、f″ −，下坡越來越陡，衝向 −∞。(1, 2)：f′ −、f″ +，從 +∞ 下來、越來越緩。(2, ∞)：f′ +、f″ +，上坡、貼近 y = x + 1。","檢查：局部極大 (0, 0) 在凹向下的左分支、局部極小 (2, 4) 在凹向上的右分支，一致。"],"answer":"凹向下 (−∞, 1)、凹向上 (1, ∞)；無反曲點"},{"title":"接續 I：三個反曲點","prompt":"f(x) = x/(x² + 1)。求凹性與反曲點。","problemId":"cx-curve-007","steps":["f′(x) = (1 − x²)(x² + 1)^{−2}。乘法法則：f″(x) = −2x(x² + 1)^{−2} + (1 − x²) · (−2)(x² + 1)^{−3} · 2x。","提出 (x² + 1)^{−3}：f″(x) = (−2x(x² + 1) − 4x(1 − x²))/(x² + 1)³ = (2x³ − 6x)/(x² + 1)³ = 2x(x² − 3)/(x² + 1)³。","零點 x = 0、±√3，都是一次因式，都換號。x < −√3：−；−√3 < x < 0：+；0 < x < √3：−；x > √3：+。","凹向上：(−√3, 0)、(√3, ∞)；凹向下：(−∞, −√3)、(0, √3)。反曲點 (−√3, −√3/4)、(0, 0)、(√3, √3/4)（f(√3) = √3/4 ≈ 0.433）。","檢查：f 是奇函數，f″ 也應該是奇函數，2x(x² − 3)/(x² + 1)³ 確實是。局部極大 (1, 1/2) 在凹向下的 (0, √3) 裡，一致。"],"answer":"3 個反曲點：x = −√3、0、√3"},{"title":"從頭做一次","prompt":"完整分析 f(x) = e^{−x²}。","problemId":"sk-031","steps":["定義域全體實數；e^{−x²} > 0，沒有 x 截距，y 截距 (0, 1)；f(−x) = f(x)，偶函數。x → ±∞ 時 −x² → −∞，f → 0，水平漸近線 y = 0。","f′(x) = −2x e^{−x²}：x < 0 遞增、x > 0 遞減，局部極大 f(0) = 1。","f″(x) = −2e^{−x²} + (−2x)(−2x)e^{−x²} = (4x² − 2)e^{−x²}，零點 x = ±1/√2 ≈ ±0.707，都換號。|x| < 1/√2 凹向下，|x| > 1/√2 凹向上。","反曲點 (±1/√2, e^{−1/2})，e^{−1/2} ≈ 0.607。檢查：極大 (0, 1) 在凹向下的段裡；兩條尾巴從上方貼近 y = 0，凹向上，一致。"],"answer":"偶函數；y = 0；極大 (0, 1)；反曲點 (±1/√2, e^{−1/2})"}],"pitfalls":["f′ 與 f″ 的切點分開列兩張表，最後拼不起來；要合成一張。","把定義域斷開的點也寫成反曲點。","極大點畫在凹向上的段裡卻沒發現矛盾。","f″ 的乘法法則或連鎖律漏一項，三個反曲點只找到一個。"],"checks":[{"ask":"某段上 f′ < 0、f″ > 0。這段曲線長什麼樣？","options":[{"label":"下坡，坡越來越緩","correct":true},{"label":"下坡，坡越來越陡","why":"越來越陡是斜率越來越負，要 f″ < 0。f″ > 0 表示斜率在變大，往 0 靠近。"},{"label":"上坡，坡越來越陡","why":"f′ < 0 是下坡。f″ > 0 只說斜率在變大，不改變它目前是負的。"}]},{"ask":"算出 f 在 x = 2 有局部極大，又算出 f 在 (1, 3) 上凹向上。這代表？","options":[{"label":"有一個算錯了","correct":true},{"label":"沒問題，兩者無關","why":"f′(2) = 0 而 (1, 3) 上凹向上，由二階判別的道理 x = 2 該是局部極小。兩個結論互相矛盾。"},{"label":"x = 2 是反曲點","why":"整段 (1, 3) 都凹向上，凹性在 2 沒有換，不是反曲點。"}]},{"ask":"f 是偶函數，f″ 會是？","options":[{"label":"偶函數","correct":true},{"label":"奇函數","why":"偶函數微分一次變奇函數（f′），再微分一次又變回偶函數。"},{"label":"不一定","why":"微分會把偶變奇、奇變偶，所以 f″ 一定是偶函數（只要存在）。"}]},{"ask":"f(x) = e^{−x²} 的反曲點 x 座標是？","options":[{"label":"±1/√2","correct":true},{"label":"0","why":"x = 0 是 f′ = 0 的點，是局部極大。反曲點要解 f″ = (4x² − 2)e^{−x²} = 0。"},{"label":"±√2","why":"4x² − 2 = 0 得 x² = 1/2，x = ±1/√2，不是 ±√2。"}]}],"practice":[{"id":"cw-001","core":true},{"id":"cx-curve-007","core":true},{"id":"sk-012","core":true},{"id":"sk-031","core":true},{"id":"cw-004","core":true},{"id":"sk-029"},{"id":"sk-020"},{"id":"gx-030"},{"id":"cw-014"},{"id":"sk-030"},{"id":"sk-023","challenge":true,"note":"挑戰：x/(x² − 1) 有兩條垂直漸近線、奇對稱，反曲點只有原點。"}]},"optimization-basics":{"id":"optimization-basics","prerequisites":["critical-points","first-derivative-test"],"next":["optimization-geometry"],"related":["extreme-value-theorem"],"objectives":["把文字題寫成一個變數的目標函數，並寫出它的定義域。","範圍是閉區間時，把臨界點和端點一起比較。","範圍是開區間或無界時，用 f′ 的正負說明唯一的臨界點就是絕對極值。"],"concept":[{"heading":"① 最佳化要的是「絕對」最大、最小","body":["〈一階導數判別〉找的是局部的山頂、谷底：比附近都高或都低。最佳化問的是整個範圍裡最高、最低的那一個，也就是絕對最大值、絕對最小值。","局部的山頂不一定是最高點：f(x) = x³ − 3x 在 x = −1 有局部極大 2，可是在 [−2, 3] 上，x = 3 的值 18 比它高得多。"]},{"heading":"② 範圍是閉區間：臨界點加端點，全部比","body":["前面學臨界點時已經有這個做法：f 在 [a, b] 連續，絕對最大、最小值一定存在（〈極值定理〉），而且只會出現在內部的臨界點或端點。全部代進去比就好，不必判斷誰是山頂。","文字題的範圍常常就是閉區間：長度至少是 0，最多用完全部材料。端點代表「極端的做法」（例如圍出寬度 0 的長方形），值往往是 0，但仍要算進來比。"]},{"heading":"③ 不是閉區間：用 f′ 的正負說話","body":["區間是開的或無界（例如 x > 0），最大最小值不保證存在，也沒有端點可以比。這時常用的論證是：f 在區間上只有一個臨界點 c，而且 f′ 在 c 左邊 < 0、右邊 > 0。那麼 f 在 c 左邊一路下降、右邊一路上升，f(c) 就是整個區間的絕對最小值（反過來就是最大值）。"]},{"heading":"④ 文字題的四步","body":["1. 決定要最大或最小的量（目標），以及可以調整的量。2. 用題目的限制條件，把目標寫成只有一個變數的函數。3. 寫出這個變數合理的範圍（長度 ≥ 0、不能超過材料）。4. 用 ② 或 ③ 求極值，最後回答題目問的東西，附單位。"]}],"workedExamples":[{"title":"閉區間的文字題：靠牆圍籬","prompt":"用 100 公尺圍籬沿一道直牆圍出長方形（牆那一側不用圍）。最大面積是多少？","problemId":"dd-opt-001","steps":["目標：面積 A。可調的量：垂直於牆的兩邊各長 x，平行於牆的一邊就是 100 − 2x。","A(x) = x(100 − 2x)。範圍：x ≥ 0 且 100 − 2x ≥ 0，所以 0 ≤ x ≤ 50。這是閉區間。","A′(x) = 100 − 4x = 0，得 x = 25。候選值：A(0) = 0、A(25) = 25 · 50 = 1250、A(50) = 0。","最大面積 1250 平方公尺：垂直牆的兩邊各 25 公尺、平行牆的一邊 50 公尺。"],"answer":"1250 平方公尺"},{"title":"開區間：唯一的臨界點","prompt":"求 f(x) = x + 4/x 在 x > 0 的最小值。","problemId":"app-007","steps":["f′(x) = 1 − 4/x² = (x² − 4)/x²。在 x > 0 上，f′ = 0 只有 x = 2。","0 < x < 2 時 x² < 4，f′ < 0，f 遞減；x > 2 時 f′ > 0，f 遞增。","先降後升，x = 2 是整個 (0, ∞) 上的最低點：f(2) = 2 + 2 = 4。"],"answer":"4","note":"沒有最大值：x → 0⁺ 或 x → ∞ 時 f(x) 都 → ∞。"},{"title":"利潤最大","prompt":"收益 R(q) = 100q − 0.5q²，成本 C(q) = 20q + 500（q 是產量，q ≥ 0）。最大利潤是多少？","problemId":"dd-mar-003","steps":["目標：利潤 P = R − C = 100q − 0.5q² − 20q − 500 = 80q − 0.5q² − 500，範圍 q ≥ 0（沒有上限，不是閉區間）。","P′(q) = 80 − q = 0，得 q = 80。","0 ≤ q < 80 時 P′ > 0、q > 80 時 P′ < 0：先升後降，q = 80 是 [0, ∞) 上的最高點。","P(80) = 6400 − 3200 − 500 = 2700。"],"answer":"2700（產量 80）"}],"pitfalls":["閉區間只看臨界點，忘了算端點。","把局部極大值當成絕對最大值。","開區間上找到 f′ = 0 就宣布是最小值，沒有說明為什麼。","文字題沒有寫變數的範圍，或保留兩個變數就開始微分。","答非所問：題目問最大利潤，只回答 q = 80。"],"checks":[{"ask":"周長 40 的長方形，一邊長 x。面積函數與 x 的範圍是？","options":[{"label":"A = x(20 − x)，0 ≤ x ≤ 20","correct":true},{"label":"A = x(40 − x)，0 ≤ x ≤ 40","why":"周長 40 是兩個長加兩個寬，長加寬只有 20，所以另一邊是 20 − x。"},{"label":"A = x(20 − x)，x 是任何實數","why":"x 是長度，要 ≥ 0；另一邊 20 − x 也要 ≥ 0，所以 x ≤ 20。"}]},{"ask":"利潤 P(q) = 80q − 0.5q² − 500（q ≥ 0）。產量多少時利潤最大？","options":[{"label":"80","correct":true},{"label":"160","why":"160 是 80q − 0.5q² = 0 的解，那是收益扣變動成本剛好歸零的地方。要解 P′(q) = 80 − q = 0。"},{"label":"2700","why":"2700 是最大利潤本身，題目問的是產量 q。"}]},{"ask":"兩個正數相乘是 16，和最小是多少？","options":[{"label":"8","correct":true},{"label":"4","why":"4 是其中一個數 x，題目問的是和 S = x + 16/x 在 x = 4 的值 8。"},{"label":"17","why":"1 × 16 是一組可能，但不是最小。S′ = 1 − 16/x² = 0 給 x = 4，S = 8。"}]},{"ask":"f 在 (0, ∞) 上只有一個臨界點 x = 2，f′ 在它左邊負、右邊正。f(2) 是？","options":[{"label":"f 在 (0, ∞) 上的絕對最小值","correct":true},{"label":"只是局部極小值，不能說是絕對最小","why":"左邊整段遞減、右邊整段遞增，區間裡沒有任何一點比 f(2) 低，所以是絕對最小。"},{"label":"f 在 (0, ∞) 上的絕對最大值","why":"先降後升是谷底，不是山頂。"}]}],"practice":[{"id":"app-007","core":true},{"id":"db-ext-005"},{"id":"db-opt-001","core":true},{"id":"tb-opt-002","core":true},{"id":"dd-opt-001","core":true},{"id":"dd-kin-002","core":true},{"id":"dd-mar-003","core":true},{"id":"dd-opt-008","core":true},{"id":"dd-mar-004"},{"id":"dd-opt-014"},{"id":"dx-eco-004"},{"id":"dx-bio-001","challenge":true,"note":"挑戰：兩個指數相減，令 C′ = 0 後取 ln 解 t。"}]},"optimization-geometry":{"id":"optimization-geometry","prerequisites":["optimization-basics"],"next":["optimization-distance"],"related":[],"objectives":["畫圖、標變數，把盒子、圓柱、內接圖形的題目寫成一個變數的函數。","用限制條件（體積固定、周長固定、頂點在圓上）消去多餘的變數。","目標函數帶根號時，改求它的平方，並說得出為什麼可以。"],"concept":[{"heading":"① 幾何題難在設定，不在微分","body":["微分本身通常不難，卡住的地方是：哪個量當變數、目標函數長什麼樣、變數可以多大。先畫圖，把會變的長度標上字母，寫出要最大或最小的量。","常用的公式：無蓋方底盒 V = 底面積 × 高；圓柱 V = πr²h，有蓋圓柱表面積 S = 2πr² + 2πrh；圓錐 V = (1/3)πr²h。"]},{"heading":"② 限制條件用來消變數","body":["圓柱的表面積有 r、h 兩個變數，但題目會給一個限制，例如體積固定 πr²h = 16π。從限制解出 h = 16/r²，代進表面積，就只剩 r 一個變數，可以用〈最佳化基本模型〉的方法。","內接圖形的限制是「頂點在曲線上」：半圓 x² + y² = 25 上的頂點滿足 y = √(25 − x²)。"]},{"heading":"③ 有根號：改求平方","body":["A(x) = 2x√(25 − x²) 微分要用乘法法則加連鎖律，容易算錯。因為 A ≥ 0，而 t ↦ t² 在 t ≥ 0 上遞增，A 越大 A² 就越大，兩者在同一個 x 取到最大。所以改求 A² = 4x²(25 − x²) 的最大值，沒有根號。","前提是 A ≥ 0。會取負值的函數不能這樣做：−3 < 1，平方後卻是 9 > 1。"]},{"heading":"④ 算完回頭看一眼","body":["答案要落在變數的範圍裡，也要合理：剪掉的角不能比紙板一半還大，半徑不能是負的。有些結果值得記住：周長固定的長方形，正方形面積最大；體積固定的有蓋圓柱，高等於直徑時最省材料。"]}],"workedExamples":[{"title":"紙板摺盒子","prompt":"邊長 12 公分的正方形紙板，四角各剪去邊長 x 的小正方形，摺成無蓋盒子。最大體積是多少？","problemId":"lec-05-q2b","steps":["盒底邊長 12 − 2x（每邊兩頭各剪 x），高 x。V(x) = x(12 − 2x)²。","範圍：x ≥ 0 且 12 − 2x ≥ 0，所以 0 ≤ x ≤ 6。","乘法法則：V′ = (12 − 2x)² + x · 2(12 − 2x)(−2) = (12 − 2x)[(12 − 2x) − 4x] = (12 − 2x)(12 − 6x)。","V′ = 0 得 x = 6 或 x = 2。比較候選值：V(0) = 0、V(6) = 0、V(2) = 2 · 8² = 128。"],"answer":"128 立方公分（x = 2）"},{"title":"最省材料的罐子","prompt":"體積 16π 的有蓋圓柱罐，表面積最小是多少？","problemId":"db-opt-005","steps":["變數：底半徑 r、高 h。目標 S = 2πr² + 2πrh；限制 πr²h = 16π，所以 h = 16/r²。","代入：S(r) = 2πr² + 2πr · 16/r² = 2πr² + 32π/r，r > 0。","S′(r) = 4πr − 32π/r² = 0，得 r³ = 8，r = 2。0 < r < 2 時 S′ < 0、r > 2 時 S′ > 0，所以 r = 2 是 (0, ∞) 上的最小值。","h = 16/4 = 4，S = 2π · 4 + 32π/2 = 8π + 16π = 24π。"],"answer":"24π（r = 2、h = 4）","note":"h = 4 = 2r：高等於直徑。換任何體積都是這個比例。"},{"title":"半圓內接矩形","prompt":"半徑 5 的半圓內接矩形，一邊落在直徑上。最大面積是多少？","problemId":"dd-opt-005","steps":["圓心放原點，半圓是 y = √(25 − x²)（y ≥ 0）。矩形右上頂點 (x, √(25 − x²))，寬 2x、高 √(25 − x²)，0 ≤ x ≤ 5。","A(x) = 2x√(25 − x²) ≥ 0，改求 A² = 4x²(25 − x²) = 100x² − 4x⁴。","(A²)′ = 200x − 16x³ = 8x(25 − 2x²) = 0，在 (0, 5) 裡得 x² = 25/2，x = 5/√2。端點 x = 0、x = 5 時 A = 0。","A = 2 · (5/√2) · √(25 − 25/2) = 2 · (5/√2) · (5/√2) = 25。"],"answer":"25"}],"pitfalls":["紙板盒子的底寫成 12 − x，忘了兩頭都剪。","保留兩個變數就開始微分，沒有先用限制條件消去。","有蓋、無蓋的表面積公式用錯。","對會取負值的函數也改求平方。","求出 x 就停了，沒有回答題目問的面積或體積。"],"checks":[{"ask":"12 × 12 紙板四角剪去邊長 x 的正方形摺成無蓋盒。x 的合理範圍是？","options":[{"label":"0 ≤ x ≤ 6","correct":true},{"label":"0 ≤ x ≤ 12","why":"每一邊兩頭各剪 x，底邊剩 12 − 2x，要 ≥ 0，所以 x ≤ 6。"},{"label":"x > 0 都可以","why":"x 大過 6，底邊 12 − 2x 變成負的，盒子不存在。"}]},{"ask":"周長 24 的長方形，面積最大是多少？","options":[{"label":"36","correct":true},{"label":"144","why":"12 是長加寬，不是邊長。長 x、寬 12 − x，A = x(12 − x) 在 x = 6 最大，6 × 6 = 36。"},{"label":"32","why":"8 × 4 是一組可能的長寬，但不是最大。A′ = 12 − 2x = 0 給正方形。"}]},{"ask":"體積固定的有蓋圓柱罐，表面積最小時，高 h 和半徑 r 的關係是？","options":[{"label":"h = 2r","correct":true},{"label":"h = r","why":"代 V = πr²h 固定、S = 2πr² + 2V/r，S′ = 0 給 2πr³ = V = πr²h，所以 h = 2r，不是 r。"},{"label":"h = r/2","why":"上下兩個蓋子的 2πr² 已經算在 S 裡；最省的是高等於直徑 2r，不是半徑的一半。"}]},{"ask":"求 A(x) = 2x√(25 − x²)（0 ≤ x ≤ 5）的最大值時，為什麼可以改求 A² 的最大值？","options":[{"label":"因為 A ≥ 0，而平方在非負數上是遞增的，A 和 A² 在同一個 x 最大","correct":true},{"label":"因為 A² 比較好微分","why":"這是改求平方的動機，不是它對的理由。好算但答案變了就沒用；保證答案不變的是 A ≥ 0。"},{"label":"任何函數都可以改求平方","why":"函數會取負值時不行：−3 < 1，平方後卻是 9 > 1，最大最小可能對調。"}]}],"practice":[{"id":"tb-opt-001","core":true},{"id":"db-opt-002","core":true},{"id":"lec-05-q2b","core":true},{"id":"db-opt-003","core":true},{"id":"dd-opt-011"},{"id":"db-opt-005","core":true},{"id":"dd-opt-002","core":true},{"id":"db-opt-006","core":true},{"id":"dd-opt-005"},{"id":"app-002"},{"id":"dd-opt-007"},{"id":"dd-opt-012"},{"id":"dd-opt-006","challenge":true,"note":"挑戰：球內接圓柱，半徑與半高滿足 r² + (h/2)² = 9。"},{"id":"app-010","challenge":true,"note":"挑戰：球內接圓錐，先把圓錐的半徑寫成高的函數。"}]},"optimization-distance":{"id":"optimization-distance","prerequisites":["optimization-geometry","chain-rule"],"next":["related-rates"],"related":[],"objectives":["求曲線上離某一點最近的點：改求距離平方的最小值。","把「先走一段、再換方式走一段」寫成時間或成本函數，用畢氏定理表示斜的那一段。","在閉區間上把端點也算進來比較，避免漏掉「直接走到底」的答案。"],"concept":[{"heading":"① 最近的點：求距離平方","body":["點 (x, y) 到 (a, b) 的距離 D = √((x − a)² + (y − b)²)。帶根號不好微分。距離一定 ≥ 0，所以跟〈幾何最佳化〉一樣，改求 D² 的最小值，在同一個點取到。","點在曲線上，就用曲線方程式把 y 換成 x，例如在 y = x² 上，D² = (x − a)² + (x² − b)²，只剩一個變數。"]},{"heading":"② 路線問題：時間 = 距離 ÷ 速度","body":["從離岸 3 公里的小島划船上岸，再沿岸跑到 8 公里外的小鎮。登陸點離島的正對點 x 公里，划的那段是斜邊 √(9 + x²)，跑的那段是 8 − x。划船時速 3、跑步時速 5，總時間 T(x) = √(9 + x²)/3 + (8 − x)/5。","成本題是同一個模型：每公里單價 × 長度，把「除以速度」換成「乘以單價」。"]},{"heading":"③ 端點也是候選","body":["x 的範圍是 [0, 8]：x = 0 是先划到正對點再全程跑，x = 8 是直接划到小鎮。這兩種走法都可能是最好的（例如划得比跑得快時，答案就是直接划過去），所以一定要跟臨界點一起比。"]},{"heading":"④ 一個好記的結果","body":["範例 2 的最佳點滿足 x/√(9 + x²) = 3/5：斜線與「垂直岸邊方向」夾角 θ 的正弦，剛好等於兩種速度的比。光在兩種介質之間也走最省時間的路，用同樣的計算推出來的就是折射定律。"]}],"workedExamples":[{"title":"拋物線上最近的點","prompt":"拋物線 y = x² 上哪些點離 (0, 3) 最近？最短距離是多少？","problemId":"dd-opt-004","steps":["D² = (x − 0)² + (x² − 3)² = x² + x⁴ − 6x² + 9 = x⁴ − 5x² + 9，x 可以是任何實數。","(D²)′ = 4x³ − 10x = 2x(2x² − 5) = 0，得 x = 0 或 x = ±√(5/2)。","D²(0) = 9；D²(±√(5/2)) = 25/4 − 25/2 + 9 = 11/4。(D²)′ 的正負：x < −√(5/2) 負、(−√(5/2), 0) 正、(0, √(5/2)) 負、x > √(5/2) 正，所以 x = ±√(5/2) 是谷底，x = 0 是局部山頂。x → ±∞ 時 D² → ∞，最小值是 11/4。","最近的點是 (±√(5/2), 5/2)，最短距離 √(11/4) = √11/2 ≈ 1.658。"],"answer":"(±√(5/2), 5/2)，最短距離 √11/2","note":"x = 0 那一點 (0, 0) 也是臨界點，但它是局部最遠，不是最近。"},{"title":"划船再跑步","prompt":"小島離岸 3 公里，沿岸 8 公里處有小鎮。划船時速 3 公里、跑步時速 5 公里。最短要多少小時？","problemId":"dd-opt-009","steps":["T(x) = √(9 + x²)/3 + (8 − x)/5，0 ≤ x ≤ 8。","T′(x) = x/(3√(9 + x²)) − 1/5（連鎖律）。令 T′ = 0：5x = 3√(9 + x²)。兩邊平方（兩邊都 ≥ 0，不會多出假解）：25x² = 81 + 9x²，x² = 81/16，x = 9/4。","候選值：T(0) = 1 + 8/5 = 2.6；T(9/4) = √(225/16)/3 + (23/4)/5 = 5/4 + 23/20 = 2.4；T(8) = √73/3 ≈ 2.848。","最少 2.4 小時，也就是 12/5 小時：划到離正對點 9/4 公里處上岸。"],"answer":"12/5 小時（x = 9/4）"},{"title":"兩盞燈之間最暗的點","prompt":"兩盞燈相距 10 公尺，亮度分別為 1 與 8，照度與距離平方成反比。兩燈之間最暗的點離第一盞燈多遠？","problemId":"dx-eng-001","steps":["離第一盞燈 x 公尺的照度 I(x) = 1/x² + 8/(10 − x)²，0 < x < 10。","I′(x) = −2/x³ + 16/(10 − x)³。令 I′ = 0：(10 − x)³ = 8x³，兩邊開立方：10 − x = 2x，x = 10/3。","I′ 的兩項都隨 x 遞增，所以 I′ 遞增，只變號一次：x < 10/3 時 I′ < 0、x > 10/3 時 I′ > 0。x = 10/3 是整段的最小值。"],"answer":"10/3 公尺","note":"最暗的點偏向比較暗的那盞燈，合理。"}],"pitfalls":["直接對 √(…) 微分，算到一半出錯；改求平方簡單得多。","時間寫成距離 × 速度。","兩邊平方解方程式之後，沒檢查有沒有多出不合的解。","閉區間題只算臨界點，忘了「直接划到底」的端點。","找到臨界點就當成最小值，沒有比較或檢查 f′ 的正負（範例 1 的 x = 0 是局部最遠）。"],"checks":[{"ask":"求 y = x² 上離 (0, 3) 最近的點，要對哪個函數求最小值最方便？","options":[{"label":"x² + (x² − 3)²","correct":true},{"label":"x + (x² − 3)","why":"距離不是水平差加垂直差。要用畢氏定理：兩個差的平方和，再開根號。"},{"label":"x² + x⁴ + 9","why":"(x² − 3)² 展開漏了中間項：x⁴ − 6x² + 9。"}]},{"ask":"划船時速 3 公里，划了 √(9 + x²) 公里。花的時間是？","options":[{"label":"√(9 + x²)/3 小時","correct":true},{"label":"3√(9 + x²) 小時","why":"時間是距離除以速度，不是乘。划 6 公里、時速 3，要 2 小時，不是 18 小時。"},{"label":"√(9 + x²) − 3 小時","why":"距離和速度單位不同，不能相減。時間 = 距離 ÷ 速度。"}]},{"ask":"D² = x⁴ − 5x² + 9 的臨界點是 0 與 ±√(5/2)。拋物線 y = x² 上離 (0, 3) 最近的距離是？","options":[{"label":"√11/2","correct":true},{"label":"3","why":"x = 0 是臨界點，但 D²(0) = 9 比 D²(±√(5/2)) = 11/4 大，它是局部最遠。"},{"label":"11/4","why":"11/4 是距離的平方。最後要開根號：√(11/4) = √11/2。"}]},{"ask":"兩盞燈相距 10 公尺，亮度 1 與 8。最暗的點離亮度 1 的燈多遠？","options":[{"label":"10/3 公尺","correct":true},{"label":"5 公尺","why":"兩盞燈亮度不同，最暗的點不會在正中間。解 I′ = 0 得 10 − x = 2x。"},{"label":"20/3 公尺","why":"方向反了：20/3 公尺是靠近亮的那盞燈，那裡比較亮。最暗的點偏向暗的燈。"}]}],"practice":[{"id":"app-008","core":true},{"id":"lec-05-q3b","core":true},{"id":"lec-05-q3c","core":true},{"id":"db-opt-004","core":true},{"id":"db-opt-008"},{"id":"dd-opt-009","core":true},{"id":"dd-opt-010","core":true},{"id":"dx-eng-001","core":true},{"id":"dx-eng-002"},{"id":"dd-opt-013"},{"id":"lec-05-q3d","challenge":true,"note":"挑戰：點 (0, a) 往下移，什麼時候最近的點變成原點？看 x ≠ 0 的臨界點什麼時候消失。"}]},"related-rates":{"id":"related-rates","prerequisites":["chain-rule","implicit-differentiation"],"next":["linear-approximation"],"related":[],"objectives":["把文字題寫成「幾個隨時間變化的量＋一條關係式」。","對關係式兩邊對 t 微分，用連鎖律帶出每個量的變化率。","微分之後才代入「此刻」的數值，並檢查答案的正負與單位。"],"concept":[{"heading":"① 綁在一起的量，變化率也綁在一起","body":["氣球每秒灌進 100 立方公分的空氣。體積 V 和半徑 r 都在隨時間變，而且永遠滿足 V = (4/3)πr³。","既然兩個量被一條式子綁住，它們變化的速度也被綁住：知道 dV/dt，就能算出 dr/dt。這種題目叫相關變率。"]},{"heading":"② 關鍵動作：整條式子對 t 微分","body":["每個會變的量都是時間 t 的函數。對 t 微分時，r³ 是「r(t) 的三次方」，要用〈連鎖律 I：兩層〉：d/dt (r³) = 3r² · dr/dt。","所以 V = (4/3)πr³ 兩邊對 t 微分，得 dV/dt = 4πr² · dr/dt。這跟〈隱函數微分〉是同一件事，只是對 t 微分，不是對 x。"],"tex":["\\frac{d}{dt}\\,r^3=3r^2\\,\\frac{dr}{dt}"]},{"heading":"③ 五個步驟","body":["1. 畫圖，替每個會變的量取名字（x、y、r、h）。2. 寫出它們之間的關係式；需要時用相似三角形或畢氏定理消去多餘的量。3. 兩邊對 t 微分。4. 代入「此刻」的數值。5. 解出要的變化率，檢查正負與單位。"]},{"heading":"④ 一定要先微分、再代數字","body":["梯子題問「梯腳離牆 3 公尺時」。如果先把 x = 3 代進 x² + y² = 25，x 就變成常數，微分後 dx/dt 那一項消失，題目給的速度用不上了。","3 只是某一瞬間的值，x 一直在變。微分要對「一直在變的式子」做，做完才停在那一瞬間代數字。"]},{"heading":"⑤ 正負號有意義","body":["變大的量變化率是正的，變小的是負的。題目問「下降的速率」，答案寫正數，但計算時 dy/dt 是負的，兩者要對得上。"]}],"workedExamples":[{"title":"梯子下滑","prompt":"5 公尺長的梯子靠牆，梯腳以每秒 1 公尺遠離牆。梯腳離牆 3 公尺時，頂端下降的速率是多少？","problemId":"dd-rr-001","steps":["命名：梯腳到牆 x、頂端高度 y，都是 t 的函數。已知 dx/dt = 1，求 dy/dt。","關係式（畢氏定理）：x² + y² = 25。","對 t 微分：2x · dx/dt + 2y · dy/dt = 0。","此刻 x = 3，由 x² + y² = 25 得 y = 4。代入：2 · 3 · 1 + 2 · 4 · dy/dt = 0，dy/dt = −6/8 = −3/4。","負號表示 y 在變小。題目問下降的速率，答 3/4 公尺／秒。"],"answer":"每秒下降 3/4 公尺（dy/dt = −3/4）"},{"title":"氣球充氣","prompt":"球形氣球以每秒 100 立方公分充氣。半徑 5 公分時，半徑的變化率是多少？","problemId":"dd-rr-003","steps":["已知 dV/dt = 100，求 dr/dt。關係式 V = (4/3)πr³。","對 t 微分：dV/dt = 4πr² · dr/dt。","代 r = 5：100 = 4π · 25 · dr/dt = 100π · dr/dt。","dr/dt = 1/π ≈ 0.318 公分／秒。"],"answer":"1/π 公分／秒","note":"灌氣速度固定，半徑卻越長越慢：r 越大，4πr² 越大，dr/dt 越小。"},{"title":"圓錐水槽：先消去多餘的量","prompt":"倒立圓錐水槽頂半徑 3 公尺、高 6 公尺，以每分鐘 2 立方公尺注水。水深 4 公尺時，水面上升的速率？","problemId":"db-rr-004","steps":["水的形狀是一個小圓錐，水面半徑 r、水深 h。V = (1/3)πr²h，有 r、h 兩個在變的量。","相似三角形：r/h = 3/6，所以 r = h/2。代進去消掉 r：V = (1/3)π(h/2)²h = πh³/12。","對 t 微分：dV/dt = (π/4)h² · dh/dt。","代 dV/dt = 2、h = 4：2 = (π/4) · 16 · dh/dt = 4π · dh/dt，dh/dt = 1/(2π) ≈ 0.159 公尺／分。"],"answer":"1/(2π) 公尺／分"}],"pitfalls":["先代數字再微分，把會變的量當成常數。","對 t 微分時漏掉連鎖律，把 d/dt (r³) 寫成 3r²。","圓錐題沒先用相似三角形消去 r，留下兩個未知的變化率。","正負號對不上：「下降的速率」是正數，但 dy/dt 是負的。","此刻其他量的值沒有算，例如梯子題的 y = 4 要從關係式求。"],"checks":[{"ask":"圓的半徑以每秒 2 公分增加。半徑 10 公分時，面積的變化率是？","options":[{"label":"40π 平方公分／秒","correct":true},{"label":"4π 平方公分／秒","why":"dA/dt = 2πr · dr/dt，你漏了 r = 10。"},{"label":"20π 平方公分／秒","why":"那是 2πr，只算了 dA/dr。還要乘 dr/dt = 2。"}]},{"ask":"梯子題問「梯腳離牆 3 公尺時」。為什麼不能先把 x = 3 代進 x² + y² = 25 再微分？","options":[{"label":"代進去 x 就變成常數，微分後 dx/dt 那一項不見了","correct":true},{"label":"可以，先代或後代結果一樣","why":"先代會得到 9 + y² = 25，對 t 微分只剩 2y · dy/dt = 0，算出 dy/dt = 0，明顯錯了。"},{"label":"因為要先算出 y = 4","why":"y = 4 確實要算，但那不是原因。問題在 x 是隨時間變的量，3 只是某一瞬間的值。"}]},{"ask":"梯腳往外拉的時候，頂端高度 y 的變化率 dy/dt 是？","options":[{"label":"負的，因為頂端在往下","correct":true},{"label":"正的，因為速率一定是正的","why":"「速率」是大小，「變化率」帶正負。y 在變小，dy/dt 是負的；題目問下降的速率時才寫正數。"},{"label":"0，因為梯子長度不變","why":"不變的是 x² + y² = 25 這個總長，x 和 y 各自都在變。"}]},{"ask":"倒立圓錐水槽滿足 V = πh³/12，注水 dV/dt = 2。水深 h = 2 時 dh/dt 是？","options":[{"label":"2/π","correct":true},{"label":"2","why":"你把 dh/dt 當成 dV/dt。要除以 dV/dh = πh²/4 = π。"},{"label":"2/(3π)","why":"你可能用了圓柱體積 πr²h，少了 1/3，得到 V = πh³/4。圓錐是 (1/3)πr²h。"}]}],"practice":[{"id":"dd-rr-013","core":true},{"id":"dd-rr-002","core":true},{"id":"lec-03-q4a","core":true},{"id":"dd-rr-012","core":true},{"id":"db-rr-003","core":true},{"id":"dd-rr-003","core":true},{"id":"dd-rr-005","core":true},{"id":"dd-rr-004","core":true},{"id":"dd-rr-009","core":true},{"id":"db-rr-007"},{"id":"dd-rr-007"},{"id":"dd-rr-008"},{"id":"db-rr-008"},{"id":"dd-rr-011"},{"id":"dx-rr-003","challenge":true,"note":"挑戰：兩船一個往南、一個往東，先寫出 2 小時後兩船的位置。"},{"id":"dd-rr-010","challenge":true,"note":"挑戰：並聯電阻 1/R = 1/R₁ + 1/R₂，三個量同時在變。"}]},"linear-approximation":{"id":"linear-approximation","prerequisites":["secant-to-tangent","derivative-definition","derivative-power-rules","derivative-trig"],"next":["differentials-error"],"related":["concavity","taylor-polynomial","taylor-error"],"objectives":["寫出 f 在 x = a 的線性近似 L(x) = f(a) + f′(a)(x − a)，並用它估計 √4.1、∛8.06 這類數。","選一個「好算又夠近」的 a。","從曲線的凹向判斷估計值偏高還是偏低。"],"concept":[{"heading":"① 放大夠多，曲線看起來就是直線","body":["把一條光滑曲線在某一點附近一直放大，它會越來越像一條直線，那條直線就是切線。所以在 a 附近，可以拿切線的高度代替曲線的高度。","這很有用：曲線的值常常難算（√4.1 是多少？），切線是一次函數，加減乘除就算得出來。"]},{"heading":"② 公式","body":["切線通過 (a, f(a))、斜率 f′(a)，所以 L(x) = f(a) + f′(a)(x − a)。L 叫做 f 在 a 的線性近似（或線性化）。","令 x = a + h，同一件事寫成 f(a + h) ≈ f(a) + f′(a)h：從已知的 f(a) 出發，走 h，高度大約變 f′(a)h。"],"tex":["f(a+h)\\approx f(a)+f'(a)\\,h"]},{"heading":"③ 怎麼選 a","body":["兩個要求：f(a) 和 f′(a) 好算；a 離要估的地方近。估 √4.1 選 a = 4（√4 = 2），估 ∛8.06 選 a = 8（∛8 = 2）。","a = 0 附近有幾個常用的：eˣ ≈ 1 + x、ln(1 + x) ≈ x、sin x ≈ x、(1 + x)ᵏ ≈ 1 + kx。三角函數的 h 要用弧度。"]},{"heading":"④ 偏高還是偏低","body":["曲線凹向下（像 √x），切線在曲線上方，估計值偏高；凹向上（像 eˣ），切線在曲線下方，估計值偏低（〈凹向上／凹向下〉）。","√4.1 的估計 2.025，真值約 2.024846，確實偏高，差約 0.00015。"]},{"heading":"為什麼誤差比 h 小得多","body":["令誤差 E(h) = f(a + h) − f(a) − f′(a)h。兩邊除以 h：E(h)/h = (f(a + h) − f(a))/h − f′(a)。h → 0 時，第一項就是導數的定義，趨向 f′(a)，所以 E(h)/h → 0。","這句話的意思是：誤差不只趨向 0，還比 h 本身更快趨向 0。f 有二階導數時可以說得更精確：誤差大約是 f″(a)h²/2，h 縮成十分之一，誤差約縮成百分之一。精確的上界在〈Taylor 誤差〉。"],"collapsible":true}],"workedExamples":[{"title":"估計 √4.1","prompt":"用 f(x) = √x 在 x = 4 的線性近似估計 √4.1。","problemId":"lec-05-m3","steps":["a = 4，h = 0.1。f(4) = √4 = 2。","f′(x) = 1/(2√x)，f′(4) = 1/(2 · 2) = 1/4。","√4.1 ≈ 2 + (1/4)(0.1) = 2.025。","√x 凹向下，這個估計偏高。真值約 2.024846。"],"answer":"2.025"},{"title":"立方根","prompt":"用線性近似估計 ∛8.06。","problemId":"dd-lin-001","steps":["選 a = 8，因為 ∛8 = 2。h = 0.06。","f(x) = x^{1/3}，f′(x) = (1/3)x^{−2/3}。f′(8) = (1/3) · 8^{−2/3} = (1/3)(1/4) = 1/12。","∛8.06 ≈ 2 + (1/12)(0.06) = 2 + 0.005 = 2.005。"],"answer":"2.005"},{"title":"角度要換成弧度","prompt":"用線性近似估計 sin 31°。","problemId":"db-lin-004","steps":["選 a = 30° = π/6，sin(π/6) = 1/2。","h 是 1°，換成弧度：h = π/180。(sin x)′ = cos x 這條公式只在弧度下成立。","f′(π/6) = cos(π/6) = √3/2。","sin 31° ≈ 1/2 + (√3/2)(π/180) = 1/2 + √3π/360 ≈ 0.51511。真值約 0.51504。"],"answer":"1/2 + √3π/360 ≈ 0.51511"}],"pitfalls":["把 f(a) 漏掉，只寫 f′(a)h。","把 f′(a) 寫成 f′(x)，得到的不是一條直線。","三角函數用角度當 h。","a 選離目標太遠，或選一個 f(a) 自己都算不出來的 a。"],"checks":[{"ask":"f(x) = x² 在 a = 3 的線性近似 L(x) 是？","options":[{"label":"9 + 6(x − 3)","correct":true},{"label":"9 + 3(x − 3)","why":"斜率要用 f′(3) = 2 · 3 = 6，不是 a = 3 本身。"},{"label":"9 + 6x","why":"少了「− a」：切線是從 x = 3 出發走 (x − 3)，不是從 0 走 x。代 x = 3 檢查：9 + 18 ≠ 9。"}]},{"ask":"用 √x 在 4 的切線估計 √4.1 得 2.025。它比真值？","options":[{"label":"偏高","correct":true},{"label":"偏低","why":"√x 凹向下，曲線彎在切線下面，切線的高度比曲線高，所以估計偏高。"},{"label":"剛好相等","why":"只有直線的線性近似才完全準。2.025² = 4.100625，比 4.1 多一點，所以 2.025 偏高。"}]},{"ask":"用 a = 0 的線性近似估計 e^{0.05}：","options":[{"label":"1.05","correct":true},{"label":"0.05","why":"漏了起點 f(0) = e⁰ = 1。線性近似是 f(0) + f′(0)h = 1 + 0.05。"},{"label":"1","why":"只寫了 f(0)，少了斜率那一項 f′(0)h = 1 × 0.05。"}]},{"ask":"用 30° 附近的線性近似估計 sin 31°，下面哪一個式子對？","options":[{"label":"1/2 + (√3/2)(π/180)","correct":true},{"label":"1/2 + (√3/2) · 1","why":"h 用了角度的 1。導數公式 (sin x)′ = cos x 是在弧度下推出來的，1° 要寫成 π/180。"},{"label":"1/2 + (1/2)(π/180)","why":"斜率是 cos 30° = √3/2，你用成 sin 30° = 1/2 了。"}]}],"practice":[{"id":"lec-05-m3","core":true},{"id":"db-tan-004","core":true},{"id":"db-lin-001","core":true},{"id":"dd-lin-002","core":true},{"id":"lec-05-q4a"},{"id":"dd-lin-003","core":true},{"id":"tb-lin-002","core":true},{"id":"tb-lin-003"},{"id":"db-lin-003"},{"id":"db-lin-004","core":true},{"id":"tb-lin-004"},{"id":"db-lin-008","challenge":true,"note":"挑戰：arctan 1.1，要記得 arctan 1 = π/4 與 (arctan x)′。"}]},"differentials-error":{"id":"differentials-error","prerequisites":["linear-approximation"],"next":["rolle-theorem"],"related":[],"objectives":["分清楚 dy（沿切線的變化）與 Δy（實際的變化），會算 dy = f′(x) dx。","用 dy 估計量測誤差傳到計算結果的大小。","算相對誤差與百分比誤差，看出 y = xⁿ 的相對誤差會放大 n 倍。"],"concept":[{"heading":"① Δy 與 dy：真的走，和沿著切線走","body":["x 變了一點點，記作 dx（也就是 Δx）。y 實際變了 Δy = f(x + dx) − f(x)。","如果不沿著曲線、改沿著切線走，y 變的是 dy = f′(x) dx。這就是〈線性近似〉換個寫法：Δy ≈ dy。","例：y = x²，x 從 3 變成 3.1。Δy = 9.61 − 9 = 0.61；dy = 2 · 3 · 0.1 = 0.6。差 0.01，正好是 (dx)²。"],"tex":["dy=f'(x)\\,dx,\\qquad \\Delta y\\approx dy"]},{"heading":"② 量測誤差會傳下去","body":["量半徑量得 r，但可能差 dr。用 r 算出來的體積 V 會差多少？就是 dV = V′(r) dr。","這是一個估計：它用切線代替曲線，dr 越小越準。題目說「用微分估計誤差」，要的就是 dV，不是精確的 ΔV。"]},{"heading":"③ 相對誤差：差多少，跟本身比","body":["差 1 公分，量的是 10 公分還是 10 公尺，意義完全不同。相對誤差 dy/y 把誤差跟本身的大小比，乘 100% 就是百分比誤差。","y = xⁿ 時，dy = n xⁿ⁻¹ dx，除以 y = xⁿ 得 dy/y = n · dx/x。半徑差 1%，面積（r²）約差 2%，體積（r³）約差 3%。指數越高，誤差放大越多。"],"tex":["\\frac{dy}{y}=n\\,\\frac{dx}{x}\\quad(y=x^n)"]}],"workedExamples":[{"title":"球的體積誤差","prompt":"量得球的半徑 10 公分，誤差最多 0.05 公分。用微分估計體積的最大誤差。","problemId":"dd-lin-004","steps":["V = (4/3)πr³，V′(r) = 4πr²。","dV = 4πr² dr = 4π · 10² · 0.05 = 20π ≈ 62.8 立方公分。","相對誤差：dV/V = 3 · dr/r = 3 · (0.05/10) = 0.015，也就是 1.5%。半徑只差 0.5%，體積差了三倍。"],"answer":"20π ≈ 62.8 立方公分（相對誤差約 1.5%）","note":"實際的 ΔV = (4/3)π(10.05³ − 10³) ≈ 63.15，跟 dV ≈ 62.83 很接近，但不相等。"},{"title":"正立方體","prompt":"正立方體的邊長量得 5 公分，誤差 0.02 公分。用微分估計體積的誤差。","problemId":"dd-lin-005","steps":["V = s³，dV = 3s² ds。","dV = 3 · 5² · 0.02 = 3 · 25 · 0.02 = 1.5 立方公分。"],"answer":"1.5 立方公分"},{"title":"反過來：要量多準","prompt":"用 A = πr² 算圓面積，要讓面積的相對誤差不超過 1%。半徑的相對誤差最多可以是多少？","steps":["dA = 2πr dr，除以 A = πr²：dA/A = 2 · dr/r。","要 |dA/A| ≤ 1%，就要 2|dr/r| ≤ 1%。","所以 |dr/r| ≤ 0.5%。"],"answer":"0.5%"}],"pitfalls":["把 dy 當成精確的 Δy。dy 是沿切線的估計。","算相對誤差時用 dy 除以 dx，應該是除以 y。","以為相對誤差在計算中保持不變；y = xⁿ 會放大成 n 倍。","f′(x) 代錯點：要代量到的值（例如 r = 10），不是誤差 0.05。"],"checks":[{"ask":"y = x³，x = 2，dx = 0.1。dy 是？","options":[{"label":"1.2","correct":true},{"label":"1.261","why":"那是實際的變化 Δy = 2.1³ − 2³ = 9.261 − 8。dy 是沿切線走：3 · 2² · 0.1 = 1.2。"},{"label":"0.3","why":"導數 3x² 要在 x = 2 取值，是 12，不是 3。12 × 0.1 = 1.2。"}]},{"ask":"球的半徑量測有 2% 的相對誤差。用微分估計，體積的相對誤差大約是？","options":[{"label":"6%","correct":true},{"label":"2%","why":"相對誤差會被放大：V 正比於 r³，dV/V = 3 · dr/r = 3 × 2%。"},{"label":"8%","why":"你把 2 取了三次方。指數 3 是乘在相對誤差前面：dV/V = 3 · dr/r，不是 (dr/r)³ 或 2³。"}]},{"ask":"在 y = f(x) 的圖上，x 往右走 dx。沿著「切線」上升的高度是？","options":[{"label":"dy = f′(x) dx","correct":true},{"label":"Δy = f(x + dx) − f(x)","why":"Δy 是沿著曲線實際上升的高度。沿切線的是 dy，兩者只是近似相等。"},{"label":"兩者完全一樣","why":"只有 f 是直線時才一樣。y = x² 從 3 走 0.1，Δy = 0.61、dy = 0.6。"}]},{"ask":"正立方體邊長量得 2 公尺，誤差 0.01 公尺。表面積 S = 6s²。用微分估計 S 的誤差：","options":[{"label":"0.24 平方公尺","correct":true},{"label":"0.12 平方公尺","why":"S′ = 12s，你可能把 6s² 微分成 6s，漏了乘 2。12 · 2 · 0.01 = 0.24。"},{"label":"0.04 平方公尺","why":"那是只有一個面 s² 的 dS = 2s ds。表面積有 6 個面，要再乘 6。"}]}],"practice":[{"id":"lec-05-q4b","core":true},{"id":"dd-lin-005","core":true},{"id":"db-lin-006","core":true},{"id":"db-lin-007","core":true}]},"rolle-theorem":{"id":"rolle-theorem","prerequisites":["continuity-definition","derivative-definition","intermediate-value-theorem","critical-points"],"next":["mean-value-theorem"],"related":["extreme-value-theorem"],"objectives":["說出 Rolle 定理的三個條件與結論，並找出定理保證的 c。","看到定理不適用的函數，指出是哪一個條件不成立。","用「f′ 沒有零點 ⇒ f 最多一個根」配合中間值定理，證明方程式恰有一個實根。"],"concept":[{"heading":"① 出發和回來一樣高，中間一定有平的地方","body":["把球往上丟，落回手上的高度跟出手時一樣。中途球一定有一個最高點，在那一瞬間速度是 0：再往前一點就開始往下掉了。","換成圖形：一條光滑的曲線從高度 h 出發，最後又回到高度 h。它如果往上走，就得在某個地方轉頭回來；往下走也一樣。轉頭的那一點，切線是水平的。"]},{"heading":"② 定理","body":["f 在 [a, b] 連續、在 (a, b) 可微，而且 f(a) = f(b)。那麼 (a, b) 裡至少有一點 c，使 f′(c) = 0。","定理只保證 c 存在，不告訴你在哪，也不保證只有一個。要找 c，就解 f′(x) = 0，再留下落在 (a, b) 裡面的解。"],"tex":["f(a)=f(b)\\ \\Longrightarrow\\ \\exists\\, c\\in(a,b),\\ f'(c)=0"]},{"heading":"③ 三個條件，缺一個就可能不成立","body":["不可微：f(x) = |x| 在 [−1, 1]。兩端都是 1，但轉頭的地方是尖角，x = 0 沒有導數，其他地方 f′ = ±1，沒有一點是 0。","不連續：f(x) = x（0 ≤ x < 1），f(1) = 0。兩端都是 0，但圖形在 x = 1 斷掉、直接掉回 0，(0, 1) 裡 f′ 處處是 1。","兩端不等高：f(x) = x 在 [0, 1]，f′ 處處是 1。"]},{"heading":"④ 最常用的地方：根的個數","body":["如果 f 有兩個根 a < b，那 f(a) = f(b) = 0，Rolle 定理說 (a, b) 裡有一點 f′ = 0。反過來講：f′ 處處不為 0 的可微函數，最多只有一個根。","〈中間值定理〉負責證明「至少一個」，Rolle 定理負責「最多一個」，合起來就是「恰好一個」（範例 3）。"]},{"heading":"證明","body":["f 在閉區間 [a, b] 連續，由〈極值定理〉，f 在 [a, b] 上取得最大值 M 與最小值 m。","情況一：M = m。那 f 在 [a, b] 上是常數，(a, b) 裡每一點都有 f′ = 0，隨便取一個 c 都行。","情況二：M ≠ m。兩者至少有一個不等於 f(a)。因為 f(a) = f(b)，這個值不是在端點取得，而是在某個內部點 c ∈ (a, b) 取得。以最大值為例（最小值同理，不等號反過來）：","對 h > 0（夠小，使 c + h 還在區間裡），f(c + h) ≤ f(c)，所以 (f(c + h) − f(c))/h ≤ 0，令 h → 0⁺ 得 f′(c) ≤ 0。對 h < 0，分子 ≤ 0、分母 < 0，商 ≥ 0，令 h → 0⁻ 得 f′(c) ≥ 0。f 在 c 可微，左右兩個極限都等於 f′(c)，所以 f′(c) = 0。"],"collapsible":true}],"workedExamples":[{"title":"找出 c","prompt":"f(x) = x² − 4x + 3 在 [1, 3] 上，找 Rolle 定理保證的 c。","problemId":"cx-mvt-004","steps":["檢查條件：多項式處處連續、可微；f(1) = 1 − 4 + 3 = 0，f(3) = 9 − 12 + 3 = 0，兩端相等。","解 f′(x) = 2x − 4 = 0，得 x = 2。","2 在 (1, 3) 裡，所以 c = 2。"],"answer":"c = 2"},{"title":"哪個條件壞掉","prompt":"f(x) = x^{2/3} 在 [−1, 1] 上，f(−1) = f(1) = 1。Rolle 定理保證有 c 使 f′(c) = 0 嗎？","steps":["f(−1) = ((−1)²)^{1/3} = 1，f(1) = 1，兩端相等；x^{2/3} = ∛(x²) 處處連續。","x ≠ 0 時 f′(x) = (2/3)x^{−1/3}，分子是 2/3，不會是 0。","x = 0 時，割線斜率 (h^{2/3} − 0)/h = h^{−1/3}，h → 0⁺ 趨向 +∞、h → 0⁻ 趨向 −∞，f′(0) 不存在。","「(−1, 1) 可微」這個條件不成立，所以定理不保證任何事；事實上也找不到 f′ = 0 的點。"],"answer":"不保證；f 在 x = 0 不可微"},{"title":"恰好一個實根","prompt":"證明 x³ + 3x + 1 = 0 恰有一個實根。","steps":["令 f(x) = x³ + 3x + 1，多項式處處連續、可微。","至少一個：f(−1) = −1 − 3 + 1 = −3 < 0，f(0) = 1 > 0。由中間值定理，(−1, 0) 裡有一個根。","最多一個：f′(x) = 3x² + 3 ≥ 3 > 0，處處不為 0。若有兩個根 a < b，Rolle 定理會給出 (a, b) 裡一點 f′ = 0，矛盾。","合起來：恰有一個實根，而且它在 (−1, 0) 裡。"],"answer":"恰有一個實根，位於 (−1, 0)"}],"pitfalls":["沒檢查條件就套，例如 |x| 在 [−1, 1] 硬要找 f′(c) = 0。","把結論記成 f(c) = 0。那是中間值定理在找根，Rolle 定理說的是導數。","c 落在端點也算進去。c 必須在開區間 (a, b) 裡。","以為 c 只有一個。定理說「至少一個」。"],"checks":[{"ask":"f 在 [a, b] 連續、(a, b) 可微、f(a) = f(b)。Rolle 定理的結論是？","options":[{"label":"(a, b) 裡至少有一點 c，f′(c) = 0","correct":true},{"label":"(a, b) 裡至少有一點 c，f(c) = 0","why":"你可能想到中間值定理找根。Rolle 定理講的是切線水平，也就是導數為 0，跟 f 本身是不是 0 無關。"},{"label":"f′((a + b)/2) = 0","why":"c 不一定在中點。例如 x³ − x 在 [0, 1]，c = 1/√3 ≈ 0.577，不是 0.5。"}]},{"ask":"f(x) = |x| 在 [−1, 1] 上找不到 f′(c) = 0。是哪個條件不成立？","options":[{"label":"在 (−1, 1) 可微","correct":true},{"label":"在 [−1, 1] 連續","why":"|x| 的圖形是一個 V，沒有斷開，是連續的。問題出在 V 的尖角：x = 0 沒有導數。"},{"label":"f(−1) = f(1)","why":"|−1| = |1| = 1，兩端等高，這個條件成立。"}]},{"ask":"f 處處可微，而且 f′(x) > 0 對所有 x 成立。方程式 f(x) = 0 有幾個實根？","options":[{"label":"最多一個","correct":true},{"label":"恰好一個","why":"Rolle 定理只排除兩個以上。至少一個要另外用中間值定理證；eˣ 的導數處處 > 0，卻沒有根。"},{"label":"無法判斷","why":"可以判斷上限：兩個根之間一定有 f′ = 0 的點，但 f′ 處處 > 0，所以不可能有兩個根。"}]},{"ask":"f(x) = x² − 4x + 3 在 [1, 3] 上，Rolle 定理保證的 c 是？","options":[{"label":"2","correct":true},{"label":"1 和 3","why":"1 和 3 是 f(x) = 0 的地方，而且是端點。題目要的是開區間裡 f′(c) = 0 的點：2x − 4 = 0。"},{"label":"0","why":"你可能把 f′(c) = 0 跟 c = 0 搞混了。解 2c − 4 = 0 得 c = 2。"}]}],"practice":[{"id":"lec-04-m2","core":true},{"id":"cx-mvt-006","core":true},{"id":"cx-mvt-004","core":true}]},"mean-value-theorem":{"id":"mean-value-theorem","prerequisites":["rolle-theorem","average-rate","secant-to-tangent"],"next":["lhopital"],"related":["increasing-decreasing","antiderivative"],"objectives":["說出均值定理：某一點的瞬間變化率等於整段的平均變化率，並找出那個 c。","用均值定理證明「f′ 處處為 0 的函數在區間上是常數」。","用 |f′| 的上界，估計 |f(b) − f(a)|。"],"concept":[{"heading":"① 某一瞬間，剛好等於平均","body":["開車 2 小時走了 200 公里，平均時速 100。中途時速表一定至少有一瞬間正好指著 100：不可能全程都比 100 慢（那走不到 200 公里），也不可能全程都比 100 快。","換成圖形：連接曲線兩端點的割線，斜率是整段的平均變化率。把這條割線平行往上或往下推，推到剛好碰到曲線的地方，切線就跟割線平行。"]},{"heading":"② 定理","body":["f 在 [a, b] 連續、在 (a, b) 可微。那麼 (a, b) 裡至少有一點 c，使 f′(c) 等於割線斜率。","f(a) = f(b) 時割線是水平的，右邊是 0，這就是〈Rolle 定理〉。均值定理是把 Rolle 定理的圖形「斜過來看」。跟 Rolle 定理一樣，它只保證 c 存在、至少一個。"],"tex":["f'(c)=\\frac{f(b)-f(a)}{b-a}"]},{"heading":"證明（從 Rolle 定理）","body":["令 m = (f(b) − f(a))/(b − a)，割線是 y = f(a) + m(x − a)。令 g(x) = f(x) − f(a) − m(x − a)，也就是曲線減掉割線的高度差。","g 在 [a, b] 連續、在 (a, b) 可微（f 減一個一次函數）。g(a) = 0；g(b) = f(b) − f(a) − m(b − a) = 0。","由 Rolle 定理，存在 c ∈ (a, b) 使 g′(c) = 0。g′(x) = f′(x) − m，所以 f′(c) = m。"],"collapsible":true},{"heading":"③ 真正的用途：從導數推回函數","body":["找 c 只是練習。均值定理真正重要，是因為它把 f′ 的資訊翻成 f 的資訊：f(b) − f(a) = f′(c)(b − a)。","f′ 處處是 0：任兩點 f(b) − f(a) = 0 · (b − a) = 0，所以 f 是常數。推論：兩個函數導數相同，就只差一個常數。這就是〈反導函數〉都要加 + C 的原因。","f′ 處處 > 0：b > a 時 f(b) − f(a) = f′(c)(b − a) > 0，所以 f 遞增（〈增減區間〉用的就是這個）。","|f′| ≤ M：|f(b) − f(a)| ≤ M|b − a|，導數有上界，函數值就不會變太快（範例 3）。"]},{"heading":"④ 這些推論都要在「區間」上","body":["f(x) = x/|x| 在 x ≠ 0 時 f′ = 0，但 x < 0 時 f = −1、x > 0 時 f = 1，不是常數。它的定義域被 0 切成兩段，兩段之間不能用均值定理。"]}],"workedExamples":[{"title":"找出 c","prompt":"f(x) = x³ 在 [0, 3]，找均值定理保證的 c。","problemId":"cx-mvt-002","steps":["條件：多項式處處連續、可微。","割線斜率：(f(3) − f(0))/(3 − 0) = (27 − 0)/3 = 9。","f′(x) = 3x²。解 3c² = 9，c² = 3，c = ±√3。","−√3 不在 (0, 3)；√3 ≈ 1.73 在裡面。所以 c = √3。"],"answer":"c = √3","note":"c 不是中點 1.5。x² 在 [0, 2] 的 c 剛好是中點 1，那是二次函數的特例。"},{"title":"時速表一定指過平均速度","prompt":"車子 2 小時的位置是 s(t) = 50t² − 10t³ + 30t（公里，0 ≤ t ≤ 2）。哪一刻的瞬時速度等於平均速度？","problemId":"dx-thm-001","steps":["平均速度：(s(2) − s(0))/2。s(2) = 200 − 80 + 60 = 180，s(0) = 0，平均 90 公里／小時。","瞬時速度 s′(t) = 100t − 30t² + 30。令它等於 90：30t² − 100t + 60 = 0，同除以 10 得 3t² − 10t + 6 = 0。","公式解：t = (10 ± √(100 − 72))/6 = (10 ± 2√7)/6 = (5 ± √7)/3。","(5 + √7)/3 ≈ 2.55 超過 2 小時，不算；(5 − √7)/3 ≈ 0.785 在 (0, 2) 裡。"],"answer":"t = (5 − √7)/3 ≈ 0.785 小時"},{"title":"用導數的上界估計差距","prompt":"證明：對所有實數 a、b，|sin a − sin b| ≤ |a − b|。","problemId":"lec-04-q2a","steps":["a = b 時兩邊都是 0，成立。以下設 a < b（a > b 時交換兩者的名字）。","f(x) = sin x 在 [a, b] 連續、在 (a, b) 可微。由均值定理，存在 c ∈ (a, b) 使 sin b − sin a = cos c · (b − a)。","取絕對值：|sin b − sin a| = |cos c| · |b − a|。","|cos c| ≤ 1，所以 |sin a − sin b| ≤ |a − b|。"],"answer":"得證"}],"pitfalls":["把 c 當成區間中點。","解出 c 之後沒有檢查它在不在 (a, b) 裡。","把 f(c) 設成平均值。均值定理要的是 f′(c) 等於割線斜率。","定理不適用的函數（有尖角、斷點）也硬套。","「f′ = 0 ⇒ 常數」用在不是區間的定義域上。"],"checks":[{"ask":"f(x) = x² 在 [0, 2]，均值定理保證的 c 是？","options":[{"label":"1","correct":true},{"label":"2","why":"2 是割線斜率 (4 − 0)/2，不是 c。要再解 f′(c) = 2c = 2。"},{"label":"√2","why":"你可能讓 f(c) = c² 等於 2。均值定理要的是導數：f′(c) = 2c = 2，c = 1。"}]},{"ask":"f 在區間 I 上可微，而且 f′(x) = 0 對所有 x ∈ I 成立。f 在 I 上是？","options":[{"label":"常數函數","correct":true},{"label":"f(x) = 0","why":"斜率是 0 表示高度不變，但可以停在任何高度：f(x) = 7 的導數也處處是 0。"},{"label":"遞增函數","why":"遞增要 f′ > 0 才保證。f′ = 0 是高度不變。"}]},{"ask":"F′(x) = G′(x) = 2x 對所有實數成立。F 和 G 的關係？","options":[{"label":"F(x) = G(x) + C，C 是某個常數","correct":true},{"label":"F = G","why":"x² 和 x² + 5 的導數都是 2x，但兩個不相等。(F − G)′ = 0 只推得出 F − G 是常數。"},{"label":"沒有關係","why":"(F − G)′ = 0，由均值定理 F − G 在整條實數線上是常數。這是 + C 的來源。"}]},{"ask":"f(x) = 1/x 在 [−1, 1]：割線斜率是 (−1 − 1)/2 = −1，但 f′(x) = −1/x² 只在 x = ±1 等於 −1，都不在 (−1, 1) 裡。為什麼？","options":[{"label":"f 在 x = 0 沒有定義，在 [−1, 1] 不連續，定理不適用","correct":true},{"label":"均值定理有例外，這是其中一個","why":"定理沒有例外，只有條件不成立。先檢查條件：1/x 在 0 斷開，不滿足「[a, b] 連續」。"},{"label":"c = 0","why":"f′(0) 根本不存在，1/x 在 0 沒有定義，c 不可能是 0。"}]}],"practice":[{"id":"lec-04-m4","core":true},{"id":"cx-mvt-002","core":true},{"id":"cx-mvt-003","core":true},{"id":"tb-mvt-001"},{"id":"tb-mvt-002","core":true},{"id":"tb-mvt-003"},{"id":"cx-mvt-005"},{"id":"dx-thm-001","core":true},{"id":"px-mvt-001","core":true},{"id":"px-mvt-002"},{"id":"lec-04-q2a","core":true},{"id":"lec-04-q2b","challenge":true,"note":"挑戰：eˣ > 1 + x，x > 0 與 x < 0 要分開用均值定理。"},{"id":"px-mvt-003","challenge":true,"note":"挑戰：自己從 Rolle 定理寫出均值定理的證明。"}]},"lhopital":{"id":"lhopital","prerequisites":["limit-factor","limit-trig-standard","derivative-power-rules","chain-rule","linear-approximation","mean-value-theorem"],"next":["indeterminate-other"],"related":["rolle-theorem","taylor-limits"],"objectives":["每次使用前都先檢查是不是 0/0 或 ∞/∞。","會處理 0/0 與 ∞/∞，必要時連續使用。","知道它什麼時候不能用、或用了沒有結論。"],"concept":[{"heading":"① 操作版：先檢查，再各自微分","body":["第一步永遠是檢查：x → a 時，分子分母是不是都 → 0，或都 → ±∞？","不是，就不能用。是，就把分子微分、分母微分，再取極限：lim_{x→a} f(x)/g(x) = lim_{x→a} f′(x)/g′(x)。a 也可以是 ±∞。"],"tex":["\\lim_{x\\to a}\\frac{f(x)}{g(x)}=\\lim_{x\\to a}\\frac{f'(x)}{g'(x)}"]},{"heading":"完整的定理條件","body":["f、g 在 a 附近（a 本身可以除外）可微；g′(x) 在 a 附近（a 本身除外）不為 0；x → a 時 f、g 都 → 0，或都 → ±∞；而且 lim_{x→a} f′(x)/g′(x) 存在（或是 ±∞）。","滿足這些，lim_{x→a} f(x)/g(x) 也存在，而且等於 lim_{x→a} f′(x)/g′(x)。a 換成 a⁺、a⁻、∞、−∞ 也成立。"],"collapsible":true},{"heading":"② 分子分母「各自」微分，不是用除法法則","body":["不是對 f/g 整個用除法法則 (f′g − fg′)/g²。那是在求 (f/g)′，跟極限無關。這是最常見的錯。"]},{"heading":"③ 一個理解 L'Hôpital 的直覺（不是證明）","body":["以 0/0 為例，假設 f(a) = g(a) = 0。在 a 附近，曲線看起來像它的切線（〈線性近似〉）：f(x) ≈ f′(a)(x − a)，g(x) ≈ g′(a)(x − a)。","兩個相除，(x − a) 約掉，剩 f′(a)/g′(a)：兩條都從 0 出發的直線，比值就是斜率的比。","這只是直覺：它假設了 f′(a)、g′(a) 存在而且 g′(a) ≠ 0，「≈」差多少也沒有交代，而且沒有涵蓋 ∞/∞。"]},{"heading":"嚴格證明（只證 x → a⁺ 的 0/0 情況）","body":["設 x → a⁺ 時 f(x) → 0、g(x) → 0；f、g 在 (a, a + δ) 可微，g′ 在那裡不為 0；lim_{x→a⁺} f′(x)/g′(x) = L。x → a⁻ 的證法對稱，兩邊合起來就是雙邊版本；∞/∞ 與 a = ±∞ 的情況另有證明。","第 1 步：補上端點。f(a)、g(a) 可能沒有定義，或不是 0；不管原本是什麼，都把它們定成 0。極限不看 a 這一點的值，所以這樣改不影響要求的極限。改完之後 f、g 在 a 右連續；在 (a, a + δ) 可微所以連續。因此對每個 x ∈ (a, a + δ)，f、g 在 [a, x] 連續、在 (a, x) 可微。","第 2 步：g(x) ≠ 0。若某個 x ∈ (a, a + δ) 使 g(x) = 0 = g(a)，由〈Rolle 定理〉，(a, x) 裡有一點 g′ = 0，跟假設矛盾。","第 3 步：柯西均值定理。固定 x，令 h(t) = f(t)·g(x) − g(t)·f(x)（t ∈ [a, x]）。h(a) = 0 − 0 = 0，h(x) = f(x)g(x) − g(x)f(x) = 0，h 在 [a, x] 連續、(a, x) 可微。由 Rolle 定理，存在 c ∈ (a, x) 使 h′(c) = f′(c)g(x) − g′(c)f(x) = 0。g′(c) ≠ 0、g(x) ≠ 0，兩邊同除以 g′(c)g(x)，得 f(x)/g(x) = f′(c)/g′(c)。這一步用到了 f(a) = g(a) = 0；一般的柯西均值定理給的是 (f(x) − f(a))/(g(x) − g(a))。","第 4 步：取極限。c 跟著 x 變，但永遠滿足 a < c < x。任給 ε > 0，因為 f′/g′ → L，可以找 η > 0（η ≤ δ）使得 a < t < a + η 時 |f′(t)/g′(t) − L| < ε。那麼只要 a < x < a + η，就有 a < c < a + η，所以 |f(x)/g(x) − L| = |f′(c)/g′(c) − L| < ε。這正是 lim_{x→a⁺} f(x)/g(x) = L。"],"tex":["\\frac{f(x)}{g(x)}=\\frac{f(x)-f(a)}{g(x)-g(a)}=\\frac{f'(c)}{g'(c)},\\qquad a<c<x"],"collapsible":true},{"heading":"④ 不是不定型就用，答案會錯","body":["lim_{x→0} (x + 1)/(x + 2) = 1/2（直接代入）。硬用 L'Hôpital：分子分母微分都是 1，得 1。錯的。"]},{"heading":"⑤ f′/g′ 沒有極限時，L'Hôpital 不說任何事","body":["lim_{x→∞} (x + sin x)/x：同除以 x，得 1 + (sin x)/x → 1。","用 L'Hôpital：(1 + cos x)/1 在 0 到 2 之間一直晃，沒有極限。這不代表原極限不存在，只代表這把鑰匙在這裡打不開，要換方法。"]},{"heading":"⑥ 可以連續用，每一次都要重新檢查","body":["微分一次後還是 0/0 或 ∞/∞，可以再用。用到三、四次通常很繁瑣，這時〈用 Taylor 求極限〉更快。"]}],"workedExamples":[{"title":"0/0","prompt":"lim_{x→1} (ln x)/(x − 1)","problemId":"cx-lh-007","steps":["檢查：ln 1 = 0、1 − 1 = 0，是 0/0。","分子微分 1/x，分母微分 1。","lim_{x→1} (1/x)/1 = 1。"],"answer":"1","note":"這正好是 ln x 在 x = 1 的導數。很多 0/0 本身就是某個導數。"},{"title":"∞/∞，用兩次","prompt":"lim_{x→∞} x²/eˣ","problemId":"cx-lh-004","steps":["檢查：分子分母都 → ∞，是 ∞/∞。","微分一次：2x/eˣ。分子分母還是都 → ∞，再檢查一次，仍是 ∞/∞。","再微分一次：2/eˣ。分母 → ∞、分子固定是 2，所以 → 0。"],"answer":"0","note":"指數成長比任何多項式都快。"},{"title":"分母是三角函數","prompt":"lim_{x→0} (e^{2x} − 1)/sin 3x","problemId":"tb-lh-001","steps":["檢查：e⁰ − 1 = 0、sin 0 = 0，是 0/0。","分子微分 2e^{2x}（連鎖律，裡層 2x 的導數是 2），分母微分 3 cos 3x（裡層 3x 的導數是 3）。","新的分式在 x = 0 連續，直接代入：2e⁰/(3 cos 0) = 2/3。"],"answer":"2/3"},{"title":"用錯的例子","prompt":"lim_{x→0} (x + 1)/(x + 2)","steps":["檢查：x = 0 時分子是 1、分母是 2，不是不定型，不能用。","直接代入，答案 1/2。沒檢查就用，會得到 1/1 = 1，是錯的。"],"answer":"1/2"}],"pitfalls":["沒檢查就用（範例 4）。","用除法法則對整個分式微分。","連鎖律漏掉，例如 e^{2x} 微分寫成 e^{2x}。","f′/g′ 沒有極限，就以為原極限不存在（觀念 ⑤）。"],"checks":[{"ask":"下面哪一個可以直接用 L'Hôpital？","options":[{"label":"lim_{x→0} (sin x)/x","correct":true},{"label":"lim_{x→0} (cos x)/x","why":"分子 → cos 0 = 1，是 1/0 型，不是 0/0。你可能只看到分母 → 0 就以為能用。"},{"label":"lim_{x→1} (x + 1)/x","why":"直接代入得 2，不是不定型。看到分式就想微分，是跳過了檢查。"}]},{"ask":"用 L'Hôpital 時，分子分母要怎麼處理？","options":[{"label":"分子微分、分母微分，各自分開","correct":true},{"label":"整個分式用除法法則微分","why":"那是求 (f/g)′，不是 L'Hôpital。兩者長得都有「微分」，容易混在一起。"},{"label":"分子分母同除以 x","why":"那是 x → ∞ 時看最高次的方法，不是 L'Hôpital。"}]},{"ask":"lim_{x→1} (x⁵ − 1)/(x³ − 1) 是？","options":[{"label":"5/3","correct":true},{"label":"1","why":"0/0 不是 1。微分後 5x⁴/(3x²)，代 1 得 5/3。"},{"label":"3/5","why":"分子分母弄反了：分子 x⁵ − 1 微分是 5x⁴，放在上面。"}]},{"ask":"lim_{x→∞} (x + sin x)/x 用 L'Hôpital 得 (1 + cos x)/1，它沒有極限。所以原極限：","options":[{"label":"是 1，要用別的方法算","correct":true},{"label":"不存在","why":"f′/g′ 沒有極限時 L'Hôpital 沒有結論，不是「原極限不存在」。同除以 x 就知道是 1。"},{"label":"是 2","why":"你可能把 cos x 當成 1 代進去。cos x 不會停在 1，這個值沒有根據。"}]}],"practice":[{"id":"cx-lh-007","core":true},{"id":"lec-05-m2","core":true,"note":"先改寫成 x/eˣ。"},{"id":"cx-lh-013","core":true,"note":"先改寫成分式。"},{"id":"tb-lh-003","core":true},{"id":"cx-lh-010","core":true},{"id":"lec-05-q1b","core":true},{"id":"tb-lh-002","core":true},{"id":"cx-lh-002","note":"連用三次，每次都要重新檢查。"},{"id":"cx-lh-001"}]},"indeterminate-other":{"id":"indeterminate-other","prerequisites":["lhopital","limit-e-type","derivative-log"],"next":["antiderivative"],"related":["continuity-definition","limit-algebra-other","limit-rationalize"],"objectives":["認得五種不定型 0·∞、∞ − ∞、1^∞、0⁰、∞⁰，也認得哪些長得像、其實不是。","把 0·∞ 與 ∞ − ∞ 改寫成 0/0 或 ∞/∞，再用 L'Hôpital。","指數型先取 ln，算完記得取 e 回來。"],"concept":[{"heading":"① 為什麼這五種叫「不定」","body":["x → 0⁺ 時，x → 0、1/x → ∞。可是 x · (1/x) = 1，x² · (1/x) = x → 0，x · (1/x²) = 1/x → ∞。三個都是「0 乘 ∞」，答案卻是 1、0、∞。","所以 0·∞ 不是一個數：一個往 0 拉、一個往 ∞ 拉，誰贏要看誰跑得快。∞ − ∞、1^∞、0⁰、∞⁰ 也一樣，只看型態決定不了答案，要算。"]},{"heading":"② 0·∞：把其中一個翻到分母","body":["f · g = f / (1/g)。這樣 0·∞ 就變成 0/0 或 ∞/∞，可以用〈L'Hôpital 法則〉。","翻哪一個？翻完之後微分要好算的那個。ln x 留在分子（它的導數 1/x 很簡單），把多項式那一邊翻下去。"]},{"heading":"③ ∞ − ∞：先合成一個分式","body":["兩個分式就通分，有平方根就乘共軛（〈0/0：有理化〉），目標都一樣：變成一個分式，再看是不是 0/0 或 ∞/∞。"]},{"heading":"④ 1^∞、0⁰、∞⁰：先取 ln","body":["y = f(x)^{g(x)}（f > 0），取 ln 得 ln y = g(x) · ln f(x)。三種情況都會變成 0·∞：1^∞ 是 ∞ · ln 1 = ∞ · 0；0⁰ 是 0 · (−∞)；∞⁰ 是 0 · ∞。","先用 ② 算出 lim ln y = L，再取 e 回來：lim y = e^L。最後一步最容易忘。"],"tex":["\\lim y=\\lim e^{\\ln y}=e^{\\lim \\ln y}"]},{"heading":"為什麼可以先算 ln y、再取 e","body":["eˣ 是連續函數（〈連續的定義〉）：只要 h(x) → L（L 是一個數），就有 e^{h(x)} → e^L。拿 h = ln y，因為 y = e^{ln y}，得到 lim y = e^L。","若 ln y → −∞，則 y = e^{ln y} → 0；若 ln y → +∞，則 y → ∞。"],"collapsible":true},{"heading":"⑤ 長得像、但不是不定型","body":["∞ + ∞ = ∞、∞ · ∞ = ∞。底數 → 0⁺、指數 → +∞ 的 0^∞ 是 0（越小的正數乘越多次越小）。這些直接下結論，不必算。"]}],"workedExamples":[{"title":"0·∞","prompt":"lim_{x→0⁺} x ln x","problemId":"lim-011","steps":["x → 0⁺、ln x → −∞，是 0·∞。","ln x 留在分子，把 x 翻下去：x ln x = (ln x)/(1/x)。現在分子 → −∞、分母 → +∞，是 ∞/∞。","L'Hôpital：分子微分 1/x，分母微分 −1/x²。","(1/x)/(−1/x²) = (1/x) · (−x²) = −x → 0。"],"answer":"0","note":"反過來把 ln x 翻下去，x/(1/ln x) 的分母微分是 −1/(x(ln x)²)，越算越亂。"},{"title":"0⁰","prompt":"lim_{x→0⁺} xˣ","problemId":"exam-lim-011","steps":["底數 → 0⁺、指數 → 0，是 0⁰。x > 0，可以取 ln。","令 y = xˣ，ln y = x ln x。","範例 1 已經算過：x ln x → 0。","取 e 回來：y → e⁰ = 1。"],"answer":"1","note":"第二條驗算是同一招用在 ∞⁰：x^{1/x} 取 ln 得 (ln x)/x → 0，所以 x → ∞ 時 x^{1/x} → 1。"},{"title":"1^∞","prompt":"lim_{x→∞} (1 + 2/x)^{3x}","problemId":"exam-lim-012","steps":["底數 → 1、指數 → ∞，是 1^∞。底數 > 0，取 ln：ln y = 3x · ln(1 + 2/x)。","這是 ∞ · 0。把 x 翻下去：ln y = 3 ln(1 + 2/x) / (1/x)，是 0/0。","分子微分：3 · (−2/x²)/(1 + 2/x)（連鎖律，裡層 2/x 的導數是 −2/x²）。分母微分：−1/x²。","相除，−1/x² 約掉：6/(1 + 2/x) → 6。","取 e 回來：y → e⁶。"],"answer":"e⁶","note":"這是〈e 型極限〉(1 + a/x)^x → eᵃ 的另一種算法：(1 + 2/x)^{3x} = ((1 + 2/x)^x)³ → (e²)³。"},{"title":"∞ − ∞","prompt":"lim_{x→0} (1/x − 1/(eˣ − 1))","problemId":"cx-lh-012","steps":["x → 0⁺ 時兩項都 → +∞（x → 0⁻ 時都 → −∞），是 ∞ − ∞。通分：(eˣ − 1 − x)/(x(eˣ − 1))。","代 0：分子 1 − 1 − 0 = 0、分母 0，是 0/0。","L'Hôpital：分子微分 eˣ − 1；分母 x(eˣ − 1) 用乘法法則，微分是 (eˣ − 1) + xeˣ。代 0 還是 0/0。","再用一次：分子微分 eˣ；分母微分 eˣ + (eˣ + xeˣ) = 2eˣ + xeˣ。","代 0：1/(2 + 0) = 1/2。"],"answer":"1/2"}],"pitfalls":["把 1^∞ 當成 1。底數只是靠近 1，不等於 1。","把 0⁰ 當成 1、把 0·∞ 當成 0。","取了 ln 算出 L，忘了答案是 e^L。","∞ − ∞ 沒有先合成一個分式，就對兩項分別用 L'Hôpital。","0·∞ 翻錯邊，把 ln x 翻到分母，越微分越複雜。"],"checks":[{"ask":"lim_{x→0⁺} x ln x 是哪一型？","options":[{"label":"0·∞","correct":true},{"label":"0，因為 0 乘任何數都是 0","why":"「0 乘任何數是 0」是對固定的數。ln x 不是一個數，它一直往 −∞ 跑；x 也只是靠近 0。"},{"label":"0/0","why":"式子是相乘，不是相除。要先改寫成 (ln x)/(1/x)，才會變成分式（而且是 ∞/∞）。"}]},{"ask":"lim_{x→∞} (1 + 1/x)ˣ 是？","options":[{"label":"e","correct":true},{"label":"1","why":"你把底數當成剛好是 1。底數只是靠近 1，指數卻一直變大，兩股力量拉扯，結果是 e。"},{"label":"∞","why":"你只看到指數 → ∞。底數同時在往 1 靠，ln y = x ln(1 + 1/x) → 1，所以極限是 e¹。"}]},{"ask":"算 lim y 時取 ln，得到 lim ln y = 0。那 lim y 是？","options":[{"label":"1","correct":true},{"label":"0","why":"0 是 ln y 的極限，不是 y 的。最後一步要取 e：y → e⁰ = 1。"},{"label":"e","why":"e = e¹，那是 ln y → 1 的情況。這裡 ln y → 0，所以是 e⁰ = 1。"}]},{"ask":"下面哪一個「不是」不定型？（底數都是正的）","options":[{"label":"底數 → 0⁺、指數 → +∞","correct":true},{"label":"底數 → 1、指數 → ∞","why":"這是 1^∞，(1 + 1/x)ˣ → e、(1 + 2/x)ˣ → e²，答案會變，所以是不定型。"},{"label":"底數 → ∞、指數 → 0","why":"這是 ∞⁰：x^{1/x} → 1，但 (eˣ)^{1/x} = e。答案會變，所以是不定型。"}]}],"practice":[{"id":"lim-011","core":true},{"id":"exam-lim-019","core":true,"note":"先把 ln(x + 1) − ln x 合成 ln(1 + 1/x)。"},{"id":"cx-lh-013","core":true},{"id":"exam-lim-011","core":true},{"id":"cx-lim-008","core":true},{"id":"exam-lim-012","core":true},{"id":"lm-os-006","core":true,"note":"看起來是 0⁰，取 ln 之後指數與 ln x 剛好抵消。"},{"id":"world-011"},{"id":"lm-os-007"},{"id":"cx-lh-012","core":true},{"id":"lec-05-q1e"},{"id":"burst-boss2-lim-001","challenge":true,"note":"挑戰：取 ln 後要用 ln(sin x / x) 的展開，或連用 L'Hôpital。"}]}});
